window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p33696f0d7e"]={"id":"p33696f0d7e","name":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）","year":2022,"region":"上海","count":65,"types":{"新思想":5,"片段阅读":15,"逻辑填空":6,"语句表达":4,"逻辑判断":15,"类比推理":9,"图形推理":11},"modules":["政治理论","言语理解与表达","判断推理"],"questions":[{"qid":"4652006","no":1,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出：马克思主义博大精深，归根到底就是一句话，                    。</p>","material":"<p>        习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是因为马克思主义行！”100年来，闪耀着真理光芒、彰显着真理力量的马克思主义指引我们走好了过往的奋斗路，也必将继续指引我们走好前方的奋进路。马克思主义是我们认识世界、把握规律、追求真理、改造世界的强大思想武器，是党和国家必须始终遵循的指导思想。习近平总书记指出：“马克思主义基本原理是普遍真理，具有永恒的思想价值，但马克思主义经典作家并没有穷尽真理，而是不断为寻求真理和发展真理开辟道路。”100年来，我们党坚定不移坚持以马克思主义为指导，同时创造性地把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，以实事求是的态度发展马克思主义，不断推进马克思主义中国化，不断开辟马克思主义新境界，创立了毛泽东思想、邓小平理论，形成了“三个代表”重要思想、科学发展观，创立了习近平新时代中国特色社会主义思想，为党和人民事业发展提供了科学理论指导。马克思主义在中国大地、在人民群众心中落地生根，充分表明了马克思主义行；马克思主义不断解答中国发展提出的新课题、回应人类社会面临的新挑战，有力证明了马克思主义行。</p>","materialNo":1,"options":[{"k":"A","t":"为人类求解放"},{"k":"B","t":"实现共产主义"},{"k":"C","t":"无产阶级专政"},{"k":"D","t":"全心全意为人民服务"}],"answer":"A","multi":false,"explanation":"<p>本题考查政治常识。<br>习近平总书记在纪念马克思诞辰200周年大会上的讲话中提到，马克思主义是人民的理论，第一次创立了人民实现自身解放的思想体系。马克思主义博大精深，归根到底就是一句话，为人类求解放。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"p33696f0d7e"},{"qid":"4651951","no":2,"type":"新思想","module":"政治理论","stem":"<p>2021年8月30日，中央全面深化改革委员会第二十一次会议指出，“十四五”时期，我国生态文明建设进入以（    ）为重点战略方向，促进经济社会发展全面绿色转型、实现生态环境质量改善由量变到质变的关键时期。</p>","material":"<p>        习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是因为马克思主义行！”100年来，闪耀着真理光芒、彰显着真理力量的马克思主义指引我们走好了过往的奋斗路，也必将继续指引我们走好前方的奋进路。马克思主义是我们认识世界、把握规律、追求真理、改造世界的强大思想武器，是党和国家必须始终遵循的指导思想。习近平总书记指出：“马克思主义基本原理是普遍真理，具有永恒的思想价值，但马克思主义经典作家并没有穷尽真理，而是不断为寻求真理和发展真理开辟道路。”100年来，我们党坚定不移坚持以马克思主义为指导，同时创造性地把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，以实事求是的态度发展马克思主义，不断推进马克思主义中国化，不断开辟马克思主义新境界，创立了毛泽东思想、邓小平理论，形成了“三个代表”重要思想、科学发展观，创立了习近平新时代中国特色社会主义思想，为党和人民事业发展提供了科学理论指导。马克思主义在中国大地、在人民群众心中落地生根，充分表明了马克思主义行；马克思主义不断解答中国发展提出的新课题、回应人类社会面临的新挑战，有力证明了马克思主义行。</p>","materialNo":1,"options":[{"k":"A","t":"节能"},{"k":"B","t":"减排"},{"k":"C","t":"降碳"},{"k":"D","t":"增效"}],"answer":"C","multi":false,"explanation":"<p>本题考查政治常识。<br>2021年8月30日，中央全面深化改革委员会第二十一次会议指出：“近年来，我们推动污染防治的措施之实、力度之大、成效之显著前所未有。‘十四五’时期，我国生态文明建设进入以降碳为重点战略方向、推动减污降碳协同增效、促进经济社会发展全面绿色转型、实现生态环境质量改善由量变到质变的关键时期，污染防治触及的矛盾问题层次更深、领域更广，要求也更高。”<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"p33696f0d7e"},{"qid":"4651966","no":3,"type":"新思想","module":"政治理论","stem":"<p>2021年9月21日，国家主席习近平出席第七十六届联合国大会一般性辩论并发表重要讲话。他指出，要把疫苗作为全球公共产品，确保发展中国家的可及性和可负担性，当务之急是要：</p>","material":"<p>        习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是因为马克思主义行！”100年来，闪耀着真理光芒、彰显着真理力量的马克思主义指引我们走好了过往的奋斗路，也必将继续指引我们走好前方的奋进路。马克思主义是我们认识世界、把握规律、追求真理、改造世界的强大思想武器，是党和国家必须始终遵循的指导思想。习近平总书记指出：“马克思主义基本原理是普遍真理，具有永恒的思想价值，但马克思主义经典作家并没有穷尽真理，而是不断为寻求真理和发展真理开辟道路。”100年来，我们党坚定不移坚持以马克思主义为指导，同时创造性地把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，以实事求是的态度发展马克思主义，不断推进马克思主义中国化，不断开辟马克思主义新境界，创立了毛泽东思想、邓小平理论，形成了“三个代表”重要思想、科学发展观，创立了习近平新时代中国特色社会主义思想，为党和人民事业发展提供了科学理论指导。马克思主义在中国大地、在人民群众心中落地生根，充分表明了马克思主义行；马克思主义不断解答中国发展提出的新课题、回应人类社会面临的新挑战，有力证明了马克思主义行。</p>","materialNo":1,"options":[{"k":"A","t":"支持和参与全球科学溯源"},{"k":"B","t":"向发展中国家无偿捐赠疫苗"},{"k":"C","t":"统筹疫情防控和经济社会发展"},{"k":"D","t":"在全球范围内公平合理分配疫苗"}],"answer":"D","multi":false,"explanation":"<p>本题考查政治常识。<br>D项正确，A、B、C三项错误，国家主席习近平9月21日在北京以视频方式出席第七十六届联合国大会一般性辩论并发表题为《坚定信心 共克时艰 共建更加美好的世界》的重要讲话。讲话指出，要把疫苗作为全球公共产品，确保发展中国家的可及性和可负担性，当务之急是要在全球范围内公平合理分配疫苗。中国将努力全年对外提供20亿剂疫苗，在向“新冠疫苗实施计划”捐赠1亿美元基础上，年内再向发展中国家无偿捐赠1亿剂疫苗。中国将继续支持和参与全球科学溯源，坚决反对任何形式的政治操弄。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"p33696f0d7e"},{"qid":"4651965","no":4,"type":"新思想","module":"政治理论","stem":"<p>1940年3月6日，中共中央首次提出了“三三制”原则，规定在根据地政权人员配备上，共产党员、党外进步人士和（    ）各占三分之一，推动了根据地的民主运动和政权建设。</p>","material":"<p>        习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是因为马克思主义行！”100年来，闪耀着真理光芒、彰显着真理力量的马克思主义指引我们走好了过往的奋斗路，也必将继续指引我们走好前方的奋进路。马克思主义是我们认识世界、把握规律、追求真理、改造世界的强大思想武器，是党和国家必须始终遵循的指导思想。习近平总书记指出：“马克思主义基本原理是普遍真理，具有永恒的思想价值，但马克思主义经典作家并没有穷尽真理，而是不断为寻求真理和发展真理开辟道路。”100年来，我们党坚定不移坚持以马克思主义为指导，同时创造性地把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，以实事求是的态度发展马克思主义，不断推进马克思主义中国化，不断开辟马克思主义新境界，创立了毛泽东思想、邓小平理论，形成了“三个代表”重要思想、科学发展观，创立了习近平新时代中国特色社会主义思想，为党和人民事业发展提供了科学理论指导。马克思主义在中国大地、在人民群众心中落地生根，充分表明了马克思主义行；马克思主义不断解答中国发展提出的新课题、回应人类社会面临的新挑战，有力证明了马克思主义行。</p>","materialNo":1,"options":[{"k":"A","t":"中间派"},{"k":"B","t":"开明地主"},{"k":"C","t":"进步官僚"},{"k":"D","t":"先进工人"}],"answer":"A","multi":false,"explanation":"<p>本题考查毛中特。<br>A项正确，B、C、D三项错误，1940年3月6日，中共中央发出毛泽东同志起草的关于《抗日根据地的政权问题》的党内指示：在政权工作人员中，共产党员、非党的左派进步分子和中间派应各占三分之一，实行“三三制”。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"p33696f0d7e"},{"qid":"4651946","no":5,"type":"新思想","module":"政治理论","stem":"<p>1949年，中国共产党在带领中国人民历经28年浴血奋战之后取得了新民主主义革命的胜利，建立了新中国。新民主主义革命的胜利为实现中华民族伟大复兴创造了根本社会条件。这具体体现在，新民主主义革命：<br>①确立了社会主义基本制度<br>②结束了旧中国一盘散沙的局面<br>③结束了旧中国半殖民地半封建社会的历史<br>④废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权</p>","material":"<p>        习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是因为马克思主义行！”100年来，闪耀着真理光芒、彰显着真理力量的马克思主义指引我们走好了过往的奋斗路，也必将继续指引我们走好前方的奋进路。马克思主义是我们认识世界、把握规律、追求真理、改造世界的强大思想武器，是党和国家必须始终遵循的指导思想。习近平总书记指出：“马克思主义基本原理是普遍真理，具有永恒的思想价值，但马克思主义经典作家并没有穷尽真理，而是不断为寻求真理和发展真理开辟道路。”100年来，我们党坚定不移坚持以马克思主义为指导，同时创造性地把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，以实事求是的态度发展马克思主义，不断推进马克思主义中国化，不断开辟马克思主义新境界，创立了毛泽东思想、邓小平理论，形成了“三个代表”重要思想、科学发展观，创立了习近平新时代中国特色社会主义思想，为党和人民事业发展提供了科学理论指导。马克思主义在中国大地、在人民群众心中落地生根，充分表明了马克思主义行；马克思主义不断解答中国发展提出的新课题、回应人类社会面临的新挑战，有力证明了马克思主义行。</p>","materialNo":1,"options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"②③④"},{"k":"D","t":"①③④"}],"answer":"C","multi":false,"explanation":"<p>本题考查毛中特。<br>①错误，从1953年起，在过渡时期总路线的指引下，中国开始对农业、手工业和资本主义工商业进行社会主义改造，并于1956年基本完成改造任务，初步建立起了社会主义的基本制度。社会主义基本制度的建立，奠定了新中国以后一切进步和发展的制度基础。<br>②③④正确，十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》中指出：“经过二十八年浴血奋斗，党领导人民，在各民主党派和无党派民主人士积极合作下，于一九四九年十月一日宣告成立中华人民共和国，实现民族独立、人民解放，彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃，也极大改变了世界政治格局，鼓舞了全世界被压迫民族和被压迫人民争取解放的斗争。”<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"政治理论"},"idx":4,"pid":"p33696f0d7e"},{"qid":"4651924","no":1,"type":"片段阅读","module":"言语理解与表达","stem":"<p>依据文段，下列判断不正确的一项是：</p>","material":"<p>        技术塑造全新的理论范式。大数据技术给公共管理带来了一场新的范式革命，这场范式革命表现在：第一，方法论范式的转型。大数据借助于云平台而具有数据搜集、分析、管理、挖掘和重组的功能，以及基于多类型数据和海量数据的预测功能，从而形成一整套基于大数据技术的方法。此类方法在大数据技术诞生前是完全没有的。其数据能实时更新，且接近于全数据，因此被广泛运用于恐怖主义研究、移民研究、战争与冲突研究、国际反腐败研究等社会科学的各个领域。面对这样一个时代和技术，传统的管理方法如定性和定量研究、比较分析、案例分析等基于“小数据”的研究方法，将更多地为数据挖掘、全数据分析等全新的研究方法所代替。简言之，“大数据+”开创了社会科学研究的新技术和新方法。第二，研究思维范式的转型。过去的案例研究、样本研究体现的是数据“精确性”思维、因果关系思维和定性思维，而借助于大数据技术，现已转向“量化”思维，即以全数据为目标的思维，以“混杂性”思维为形式，以量化数据值之间的“相关关系”为核心内容。单纯的“计算社会科学”也并不完全反映“量化”思维。第三，研究对象的转变。大数据技术诞生前，公共管理的对象是人及其相互关系。人既成为管理对象，也成为管理的工具，结果是人成为管理者的“被管理者”。大数据的公共管理对象是人所有活动所产生的数据，目的是用数据及其产生的价值来为人服务，体现了人本主义管理思想。第四，绩效检验方式的转变。此前，绩效检验的目的是以政策的落实和政策对人发挥规制作用来衡量，但政策是否科学则容易被忽视，而且，往往采取刚性强制手段。就是说政策确实发挥了作用，但人也可能因强制而对政策产生抱怨，甚至有些情况下有些人成为反政策的一员。大数据条件下的绩效检验则强调技术对人的所有社会活动产生的数据进行收集、整理、分析，最终使数据通过服务于人来体现其价值，使人在享受价值服务的过程中自觉维护良好的秩序。</p><p>        从具体的实践层面看，也有了变化。第一，大数据技术使公共管理的实践内容从流量管理向数据管理转化。传统的公共管理尤其强调流程的重要性，这主要是基于行政的科层体制。但在实践中，这会慢慢演变成流程的刻板化，效率日趋下降，甚至影响流程的合法性。而大数据技术则专注于对管理对象的数据收集、分析，它管理的对象是数据，核心是对数据进行处理。第二，大数据使公共管理的实践从事后机械应对转向智能化预先治理。传统的方式，无论是管理还是治理，都是出现了问题才采取措施。即便有所谓的预防性治理或预防性管理，也常常非常盲目，甚至可能没有任何针对性。因此，其典型特征就是事后的机械性。大数据条件下则截然不同，其核心就是预测。它通常被视为人工智能的一部分，是把数学算法运用到海量的数据上来预测事情发生的可能性。之所以能够成功，关键在于它是建立在海量数据的基础之上的，而不是基于某个人的主观判断。</p>","materialNo":1,"options":[{"k":"A","t":"大数据极大地改变了我们的研究思维"},{"k":"B","t":"传统的公共管理方法如定性和定量研究的数据不能实时更新"},{"k":"C","t":"虽然有大量计算的存在，但大数据不等同于“计算社会科学”"},{"k":"D","t":"传统的公共管理是“量化”思维"}],"answer":"D","multi":false,"explanation":"<p>A项，根据第一段“大数据技术给公共管理带来了一场新的范式革命，这场范式革命表现在······第二，研究中的思维范式转型”可知，大数据改变了我们的研究思维，表述正确，排除；<br>B项，根据第一段“大数据借助于云平台······从而形成一整套基于大数据技术的方法。此类方法在大数据技术诞生前是完全没有的。由于其数据能实时更新”可知，数据实时更新属于大数据诞生后的新方法，传统的数据不能实时更新，表述正确，排除；<br>C项，根据第一段“而借助于大数据技术，已转向‘量化’思维······单纯的‘计算社会科学’也并不完全反映‘量化’思维”可知，大数据与“计算社会科学”存在差别，表述正确，排除；<br>D项，根据第一段“过去的案例研究、样本研究体现的是数据‘精确性’思维、因果关系思维和定性思维，而借助于大数据技术，已转向‘量化’思维”可知，传统的公共管理是“精确性”思维、因果关系思维和定性思维，表述错误，当选。<br>本题为选非题，故正确答案为D。<br>【文段出处】中国社科网《胡键：大数据技术与公共管理范式的转型》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":5,"pid":"p33696f0d7e"},{"qid":"4651927","no":2,"type":"片段阅读","module":"言语理解与表达","stem":"<p>依据文段，下列陈述不正确的一项是：</p>","material":"<p>        技术塑造全新的理论范式。大数据技术给公共管理带来了一场新的范式革命，这场范式革命表现在：第一，方法论范式的转型。大数据借助于云平台而具有数据搜集、分析、管理、挖掘和重组的功能，以及基于多类型数据和海量数据的预测功能，从而形成一整套基于大数据技术的方法。此类方法在大数据技术诞生前是完全没有的。其数据能实时更新，且接近于全数据，因此被广泛运用于恐怖主义研究、移民研究、战争与冲突研究、国际反腐败研究等社会科学的各个领域。面对这样一个时代和技术，传统的管理方法如定性和定量研究、比较分析、案例分析等基于“小数据”的研究方法，将更多地为数据挖掘、全数据分析等全新的研究方法所代替。简言之，“大数据+”开创了社会科学研究的新技术和新方法。第二，研究思维范式的转型。过去的案例研究、样本研究体现的是数据“精确性”思维、因果关系思维和定性思维，而借助于大数据技术，现已转向“量化”思维，即以全数据为目标的思维，以“混杂性”思维为形式，以量化数据值之间的“相关关系”为核心内容。单纯的“计算社会科学”也并不完全反映“量化”思维。第三，研究对象的转变。大数据技术诞生前，公共管理的对象是人及其相互关系。人既成为管理对象，也成为管理的工具，结果是人成为管理者的“被管理者”。大数据的公共管理对象是人所有活动所产生的数据，目的是用数据及其产生的价值来为人服务，体现了人本主义管理思想。第四，绩效检验方式的转变。此前，绩效检验的目的是以政策的落实和政策对人发挥规制作用来衡量，但政策是否科学则容易被忽视，而且，往往采取刚性强制手段。就是说政策确实发挥了作用，但人也可能因强制而对政策产生抱怨，甚至有些情况下有些人成为反政策的一员。大数据条件下的绩效检验则强调技术对人的所有社会活动产生的数据进行收集、整理、分析，最终使数据通过服务于人来体现其价值，使人在享受价值服务的过程中自觉维护良好的秩序。</p><p>        从具体的实践层面看，也有了变化。第一，大数据技术使公共管理的实践内容从流量管理向数据管理转化。传统的公共管理尤其强调流程的重要性，这主要是基于行政的科层体制。但在实践中，这会慢慢演变成流程的刻板化，效率日趋下降，甚至影响流程的合法性。而大数据技术则专注于对管理对象的数据收集、分析，它管理的对象是数据，核心是对数据进行处理。第二，大数据使公共管理的实践从事后机械应对转向智能化预先治理。传统的方式，无论是管理还是治理，都是出现了问题才采取措施。即便有所谓的预防性治理或预防性管理，也常常非常盲目，甚至可能没有任何针对性。因此，其典型特征就是事后的机械性。大数据条件下则截然不同，其核心就是预测。它通常被视为人工智能的一部分，是把数学算法运用到海量的数据上来预测事情发生的可能性。之所以能够成功，关键在于它是建立在海量数据的基础之上的，而不是基于某个人的主观判断。</p>","materialNo":1,"options":[{"k":"A","t":"大数据下的公共管理体现了人本思想"},{"k":"B","t":"传统的公共管理往往有一种强制性"},{"k":"C","t":"传统的公共管理有预测性"},{"k":"D","t":"基于大数据的管理是客观的"}],"answer":"C","multi":false,"explanation":"<p>A项，根据文章第一段“大数据的公共管理对象是人所有活动所产生的数据，目的是用数据及其产生的价值来为人服务，体现了人本主义管理思想”可知，表述正确，排除；<br>B项，根据文章第一段“此前，绩效检验的目的是以政策的落实和政策对人发挥规制作用来衡量，但政策是否科学则容易被忽视，而且，往往采取刚性强制手段”可知，表述正确，排除；<br>C项，根据文章第二段“传统的方式，无论是管理还是治理，都是出现了问题才采取措施······其典型特征就是事后的机械性。大数据条件下则截然不同，其核心就是预测”可知，具有预测性的是大数据而非传统方式，偷换概念，当选；<br>D项，根据文章第二段“大数据条件下则截然不同······之所以能够成功，关键在于它们是建立在海量数据的基础之上的，而不是某个人的主观判断”可知，表述正确，排除。<br>本题为选非题，故正确答案为C。<br>【文段出处】中国社科网《胡键：大数据技术与公共管理范式的转型》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":6,"pid":"p33696f0d7e"},{"qid":"4651929","no":3,"type":"片段阅读","module":"言语理解与表达","stem":"<p>第一段论述的结构属于：</p>","material":"<p>        技术塑造全新的理论范式。大数据技术给公共管理带来了一场新的范式革命，这场范式革命表现在：第一，方法论范式的转型。大数据借助于云平台而具有数据搜集、分析、管理、挖掘和重组的功能，以及基于多类型数据和海量数据的预测功能，从而形成一整套基于大数据技术的方法。此类方法在大数据技术诞生前是完全没有的。其数据能实时更新，且接近于全数据，因此被广泛运用于恐怖主义研究、移民研究、战争与冲突研究、国际反腐败研究等社会科学的各个领域。面对这样一个时代和技术，传统的管理方法如定性和定量研究、比较分析、案例分析等基于“小数据”的研究方法，将更多地为数据挖掘、全数据分析等全新的研究方法所代替。简言之，“大数据+”开创了社会科学研究的新技术和新方法。第二，研究思维范式的转型。过去的案例研究、样本研究体现的是数据“精确性”思维、因果关系思维和定性思维，而借助于大数据技术，现已转向“量化”思维，即以全数据为目标的思维，以“混杂性”思维为形式，以量化数据值之间的“相关关系”为核心内容。单纯的“计算社会科学”也并不完全反映“量化”思维。第三，研究对象的转变。大数据技术诞生前，公共管理的对象是人及其相互关系。人既成为管理对象，也成为管理的工具，结果是人成为管理者的“被管理者”。大数据的公共管理对象是人所有活动所产生的数据，目的是用数据及其产生的价值来为人服务，体现了人本主义管理思想。第四，绩效检验方式的转变。此前，绩效检验的目的是以政策的落实和政策对人发挥规制作用来衡量，但政策是否科学则容易被忽视，而且，往往采取刚性强制手段。就是说政策确实发挥了作用，但人也可能因强制而对政策产生抱怨，甚至有些情况下有些人成为反政策的一员。大数据条件下的绩效检验则强调技术对人的所有社会活动产生的数据进行收集、整理、分析，最终使数据通过服务于人来体现其价值，使人在享受价值服务的过程中自觉维护良好的秩序。</p><p>        从具体的实践层面看，也有了变化。第一，大数据技术使公共管理的实践内容从流量管理向数据管理转化。传统的公共管理尤其强调流程的重要性，这主要是基于行政的科层体制。但在实践中，这会慢慢演变成流程的刻板化，效率日趋下降，甚至影响流程的合法性。而大数据技术则专注于对管理对象的数据收集、分析，它管理的对象是数据，核心是对数据进行处理。第二，大数据使公共管理的实践从事后机械应对转向智能化预先治理。传统的方式，无论是管理还是治理，都是出现了问题才采取措施。即便有所谓的预防性治理或预防性管理，也常常非常盲目，甚至可能没有任何针对性。因此，其典型特征就是事后的机械性。大数据条件下则截然不同，其核心就是预测。它通常被视为人工智能的一部分，是把数学算法运用到海量的数据上来预测事情发生的可能性。之所以能够成功，关键在于它是建立在海量数据的基础之上的，而不是基于某个人的主观判断。</p>","materialNo":1,"options":[{"k":"A","t":"递进关系"},{"k":"B","t":"总分关系"},{"k":"C","t":"并列关系"},{"k":"D","t":"条件关系"}],"answer":"B","multi":false,"explanation":"<p>文段开篇指出大数据技术给公共管理带来了新的范式革命，接下来通过第一“方法论范式的转型”、第二“研究中的思维范式转型”、第三“研究对象的转变”、第四“绩效检验方式的转变”进行具体论述，故文段属于观点＋解释说明的总分结构，对应B项。<br>A项、C项、D项均不属于总分关系，排除。<br>故正确答案为B。<br>【文段出处】中国社科网《胡键：大数据技术与公共管理范式的转型》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":7,"pid":"p33696f0d7e"},{"qid":"4651932","no":4,"type":"片段阅读","module":"言语理解与表达","stem":"<p>上述文段的核心思想是论：</p>","material":"<p>        技术塑造全新的理论范式。大数据技术给公共管理带来了一场新的范式革命，这场范式革命表现在：第一，方法论范式的转型。大数据借助于云平台而具有数据搜集、分析、管理、挖掘和重组的功能，以及基于多类型数据和海量数据的预测功能，从而形成一整套基于大数据技术的方法。此类方法在大数据技术诞生前是完全没有的。其数据能实时更新，且接近于全数据，因此被广泛运用于恐怖主义研究、移民研究、战争与冲突研究、国际反腐败研究等社会科学的各个领域。面对这样一个时代和技术，传统的管理方法如定性和定量研究、比较分析、案例分析等基于“小数据”的研究方法，将更多地为数据挖掘、全数据分析等全新的研究方法所代替。简言之，“大数据+”开创了社会科学研究的新技术和新方法。第二，研究思维范式的转型。过去的案例研究、样本研究体现的是数据“精确性”思维、因果关系思维和定性思维，而借助于大数据技术，现已转向“量化”思维，即以全数据为目标的思维，以“混杂性”思维为形式，以量化数据值之间的“相关关系”为核心内容。单纯的“计算社会科学”也并不完全反映“量化”思维。第三，研究对象的转变。大数据技术诞生前，公共管理的对象是人及其相互关系。人既成为管理对象，也成为管理的工具，结果是人成为管理者的“被管理者”。大数据的公共管理对象是人所有活动所产生的数据，目的是用数据及其产生的价值来为人服务，体现了人本主义管理思想。第四，绩效检验方式的转变。此前，绩效检验的目的是以政策的落实和政策对人发挥规制作用来衡量，但政策是否科学则容易被忽视，而且，往往采取刚性强制手段。就是说政策确实发挥了作用，但人也可能因强制而对政策产生抱怨，甚至有些情况下有些人成为反政策的一员。大数据条件下的绩效检验则强调技术对人的所有社会活动产生的数据进行收集、整理、分析，最终使数据通过服务于人来体现其价值，使人在享受价值服务的过程中自觉维护良好的秩序。</p><p>        从具体的实践层面看，也有了变化。第一，大数据技术使公共管理的实践内容从流量管理向数据管理转化。传统的公共管理尤其强调流程的重要性，这主要是基于行政的科层体制。但在实践中，这会慢慢演变成流程的刻板化，效率日趋下降，甚至影响流程的合法性。而大数据技术则专注于对管理对象的数据收集、分析，它管理的对象是数据，核心是对数据进行处理。第二，大数据使公共管理的实践从事后机械应对转向智能化预先治理。传统的方式，无论是管理还是治理，都是出现了问题才采取措施。即便有所谓的预防性治理或预防性管理，也常常非常盲目，甚至可能没有任何针对性。因此，其典型特征就是事后的机械性。大数据条件下则截然不同，其核心就是预测。它通常被视为人工智能的一部分，是把数学算法运用到海量的数据上来预测事情发生的可能性。之所以能够成功，关键在于它是建立在海量数据的基础之上的，而不是基于某个人的主观判断。</p>","materialNo":1,"options":[{"k":"A","t":"大数据技术下公共管理范式的转型"},{"k":"B","t":"传统公共管理与大数据下公共管理的区别"},{"k":"C","t":"大数据技术赋予公共管理的特色"},{"k":"D","t":"传统公共管理向大数据技术管理转变的必要性"}],"answer":"A","multi":false,"explanation":"<p>本文围绕“大数据技术”“公共管理”展开，第一自然段从“理论范式”层面介绍了“大数据技术”给“公共管理”带来的四个变化，第二自然段从“实践”层面介绍“大数据技术”给“公共管理”带来的两个变化，故本文从理论、实践两个层面介绍了“大数据技术”给“公共管理”带来的变化，对应A项。<br>B项，本文重点强调“大数据技术”给“公共管理”带来的变化，而非两种公共管理的区别，排除；<br>C项，“特色”强调独特性、与众不同，而本文强调“大数据技术”给“公共管理”带来的变化，排除；<br>D项，“必要性”指传统公共管理必须向大数据技术管理转变，而本文是对“大数据技术”已经给“公共管理”带来变化的客观陈述，偏离重点，排除。<br>故正确答案为A。<br>【文段出处】中国社科网《胡键：大数据技术与公共管理范式的转型》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":8,"pid":"p33696f0d7e"},{"qid":"4651940","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>孙坚驱散海贼所采用的策略是<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"虚张声势"},{"k":"B","t":"分进合击"},{"k":"C","t":"请君入瓮"},{"k":"D","t":"擒贼擒王"}],"answer":"A","multi":false,"explanation":"<p>第二段“坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走”，译为“孙坚就要持刀上岸，用手向东西指挥，好似分派部署人马包抄海盗的样子。盗贼们远远看见，以为官兵来捕捉他们，当即扔下财物四散而逃”，可知孙坚的策略是假造官府的声势，吓唬海贼，对应A项“虚张声势”。<br>B项“分进合击”即几股兵力从几条路线攻击一个目标，合作完成围歼任务，C项“请君入瓮”比喻以其人之道还治其人之身，D项“擒贼擒王”即捉贼先捉贼的头领，均与孙坚的策略不符，排除。<br>故正确答案为A。<br>【文段出处】《三国志卷四十六•吴书一》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":9,"pid":"p33696f0d7e"},{"qid":"4651943","no":6,"type":"片段阅读","module":"言语理解与表达","stem":"<p>本文说明孙坚            。</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"足智多谋"},{"k":"B","t":"智勇双全"},{"k":"C","t":"勇猛过人"},{"k":"D","t":"身先士卒"}],"answer":"B","multi":false,"explanation":"<p>由第二段“坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状”，译为“孙坚就要持刀上岸，用手向东西指挥，好似分派部署人马包抄海盗的样子”，可知孙坚富有智慧。由第二段“坚追，斩得一级以还”，译为“孙坚追去，砍下一个盗贼的首级回来”，第三段“会稽妖贼许昌起于句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千余人，与州郡合讨破之”，译为“熹平元年会稽郡贼人许昌在句章县谋反，自称为阳明皇帝，与他的儿子许韶煽动周围各县，共召集几万人。孙坚以郡司马的身份召兵，共得千余人。与州郡共同合作讨伐并消灭了许昌”，可知孙坚不仅勇追海贼，取得贼人首级，还召兵仅千余人，便与州郡合作消灭几万敌人，均可证明他处事勇敢。故孙坚既有智慧，又很勇敢，对应B项“智勇双全”。<br>A项，“足智多谋”即富有智慧，善于谋划，不能体现孙坚处事勇敢，表述片面，排除；<br>C项，“勇猛过人”即比别人勇敢，不能体现孙坚的智慧，表述片面，排除；<br>D项，“身先士卒”即作战时，将帅亲自上阵，冲在士兵前面，并非文段强调的重点，排除。<br>故正确答案为B。<br>【文段出处】《三国志卷四十六•吴书一》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":10,"pid":"p33696f0d7e"},{"qid":"4651947","no":7,"type":"片段阅读","module":"言语理解与表达","stem":"<p>“与其子韶扇动诸县”的意思是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"与他的儿子（许）韶一起煽动各县"},{"k":"B","t":"参与他的儿子（许）韶煽动各县的阴谋"},{"k":"C","t":"和他的一个儿子韶扇走动（于）各县"},{"k":"D","t":"给他一个叫子韶的人去煽动各县（参与起义）"}],"answer":"A","multi":false,"explanation":"<p>“与”意思是和，“其”在文中代指许昌，“韶”是许昌儿子的名字，“扇动”同煽动，故全句意思是和他（许昌）的儿子韶一起煽动各县（参与起义），对应A项。<br>B项，“与”并非参与之意，排除；<br>C项，“韶”为许昌儿子的名字，而非“韶扇”，排除；<br>D项，句中“与”并非给的意思，且“韶”为名字，而非“子韶”，排除。<br>故正确答案为A。<br>【文段出处】《三国志卷四十六•吴书一》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":11,"pid":"p33696f0d7e"},{"qid":"4651949","no":8,"type":"片段阅读","module":"言语理解与表达","stem":"<p>本文的主要内容是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"说明孙坚的性格特征"},{"k":"B","t":"讲述孙坚擒拿海贼的故事"},{"k":"C","t":"描述孙坚投笔从戎的过程"},{"k":"D","t":"记述孙坚早年的事迹"}],"answer":"D","multi":false,"explanation":"<p>第一段介绍孙坚的姓名来历，第二段讲述了孙坚十七岁时平定海贼的事迹，第三段讲述孙坚讨伐并歼灭许昌的事迹，随后得到了皇帝的任命。故本文主要介绍了孙坚年轻时候平定叛乱的事迹，对应D项。<br>A项，“性格特征”非重点，排除；<br>B项，只对应文中第二段，表述片面，排除；<br>C项，文中没有提到“投笔从戎”，排除。<br>故正确答案为D。<br>【文段出处】《三国志卷四十六•吴书一》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":12,"pid":"p33696f0d7e"},{"qid":"4651917","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>科技一直在改变社会：通讯技术<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了时空的距离，互联网等新科技<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了学习知识的成本，人工智能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了越来越多的工作岗位，基因技术<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了人类的价值观······这些改变有的已经发生，有的愈演愈烈。<br>填入画横线处的词语最恰当的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"缩短 改变 取代 减少"},{"k":"B","t":"缩短 减少 取代 改变"},{"k":"C","t":"减少 取代 缩短 改变"},{"k":"D","t":"减少 缩短 改变 取代"}],"answer":"B","multi":false,"explanation":"<p>第一空，横线处所填词语搭配“时空的距离”，A、B两项“缩短”指使原有长度、距离、时间变短，搭配得当，保留；C、D两项“减少”指减去一部分，与“时空的距离”搭配不当，排除。<br>第二空，横线处所填词语搭配“学习知识的成本”，B项“减少”搭配得当，保留；A项“改变”指事物发生显著的差别，置于此处搭配不当，排除。<br>第三空，代入验证，B项“人工智能取代工作岗位”搭配得当，保留。<br>第四空，代入验证，B项“改变人类的价值观”，搭配得当，当选。<br>故正确答案为B。<br>【文段出处】《韩少功：文理互盲，还是文理互补》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":13,"pid":"p33696f0d7e"},{"qid":"4651920","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>真正的精英，有一种夯实金字塔基础的抱负，有一种纠正时代错误的使命感。他们离成功的标尺越远，就越能心无旁骛地实现宏图大志。<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>精英与世俗意义上的成功无缘，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>成功实在<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>精英坚守自身信念的副产品而已。<br>填入画横线处的词语最恰当的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"当然 不是 就是 只是"},{"k":"B","t":"当然 不是 而是 不过是"},{"k":"C","t":"因此 虽然 但是 不过是"},{"k":"D","t":"因此 虽然 而是 只是"}],"answer":"B","multi":false,"explanation":"<p>本题可从第二、三空入手，根据“······精英与世俗意义上的成功无缘”和“成功实在······精英坚守自身信念的副产品而已”可知，前后语义相反，横线处应填入能体现相反关系的关联词，B项“不是······而是······”能体现相反关系，保留。A项“不是······就是······”表示选择关系，排除；C项“虽然······但是······”表示转折关系，填入文段，前后语义相矛盾，排除；D项“虽然······而是······”关联词搭配不当，且填入文段，前后逻辑不符，排除。<br>第一空，代入验证，B项“当然”表示合乎情理，没有疑问之意，符合语境，保留。<br>第四空，代入验证，“不过是精英坚守自身信念的副产品而已”，符合语境，B项当选。<br>故正确答案为B。<br>【文段出处】《〈无问西东〉问精英》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":14,"pid":"p33696f0d7e"},{"qid":"4651925","no":11,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>在5000多年文明发展中<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的中华优秀传统文化，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>着中华民族最深层的精神追求，代表着中华民族<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的精神标识。<br>填入画横线处的词语最恰当的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"形成 反映 自主"},{"k":"B","t":"创造 顺应 崇高"},{"k":"C","t":"传承 擘画 展示"},{"k":"D","t":"孕育 积淀 独特"}],"answer":"D","multi":false,"explanation":"<p>第一空，搭配“中华优秀传统文化”，且要表达出“文明发展”促使“文化”产生之意。A项“形成”指通过发展变化而成为某种事物或出现或发生某种情况，B项“创造”是指首先想出或做出前所未有的事物，D项“孕育”指怀胎而生育，或指一样事物衍生及帮助了另一样事物的发展生长，均可体现出文化产生之意，保留。C项“传承”指传授、继承，文明发展和文化之间不存在传授和继承的关系，排除。<br>第二空，搭配“精神追求”，且要表达出文化带来了中华民族的精神追求之意。D项“积淀”指在长期积累中形成（多用于抽象事物），符合文意，保留。A项“反映”比喻把客观事物的实质表现出来，与文意不符，排除；B项“顺应”指顺着某种趋势去适应，文段未提及文化适应精神追求，且与“精神追求”搭配不当，排除。<br>第三空，代入验证，“独特的精神标识”搭配恰当，D项当选。<br>故正确答案为D。<br>【文段出处】《【每日一习话】文化自信是更基础、更广泛、更深厚的自信》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":15,"pid":"p33696f0d7e"},{"qid":"4651930","no":12,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>一部真正意义上的通史，决非只是对史事的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，而是要努力探求历史变迁的内在联系。所以通史不仅指史事在时序上的先后承继、转合<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，而且还包括历史文化中各重要问题的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>与变迁的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，即所谓“通古今之变，成一家之言”。<br>填入画横线处的词语最恰当的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"客观描述 变幻 沿革 理性诠释"},{"k":"B","t":"客观演绎 变幻 延革 感性抒发"},{"k":"C","t":"主观判断 变换 延革 理性描述"},{"k":"D","t":"主观诠释 变换 沿革 客观评价"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“决非只是······而是”可知，横线处与后文“探求历史变迁的内在联系”应构成反义关系，即横线处要体现出没有人为干预的意思，A项“客观描述”、B项“客观演绎”均符合文意，保留。C项“主观判断”、D项“主观诠释”均侧重强调人为干预，与文意相悖，排除。<br>第二空，A、B两项均为“变幻”，保留。<br>第三空，根据“先后承继”“变迁”等可知，横线处要体现出问题的延续，A项“沿革”指事物发展、变化的历程，保留。B项“延革”为词语的误用，实际词典中不存在这一词语，误用后与“沿革”含义一致，保留。<br>第四空，依据文段主题词“通史”可知，“通史”的特点应该是客观严谨，A项“理性诠释”能体现出“通史”客观性这一特点，当选。B项“感性抒发”与通史客观的特性不符，排除。<br>故正确答案为A。<br>【文段出处】蒋廷黻-《中国近代史》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":16,"pid":"p33696f0d7e"},{"qid":"4651938","no":13,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>“两弹一星”功勋奖章获得者于敏院士回忆起研发的往事时说：“一个人的名字，早晚是要没有的，能把<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的力量融进祖国的强盛之中，便足以自慰了。”这样的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>至今仍<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线处的词语最恰当的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"单薄 金玉良言 振聋发聩"},{"k":"B","t":"微薄 金玉良言 掷地有声"},{"k":"C","t":"微薄 肺腑之言 掷地有声"},{"k":"D","t":"单薄 肺腑之言 振聋发聩"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据于敏院士的话和横线后“融进祖国的强盛之中”可知，于敏院士认为个人荣誉不重要，应以国家为重，故横线处要体现祖国强盛之中的一股小小力量，A、D两项“单薄”多形容穿衣少或身体瘦弱，B、C两项“微薄”指微小单薄，“微薄”更贴合文意且“微薄的力量”属于常见搭配，保留B、C两项，排除A、D两项。<br>第二空，横线处指代前文于敏院士的话，B项“金玉良言”指像黄金和美玉一样宝贵的忠告或教诲，C项“肺腑之言”指发自内心的真诚的话，根据文意，这句话是于敏院士对研发“两弹一星”时的感慨，并非对他人的忠告和教诲，两项对比，“肺腑之言”更贴合文意，保留C项，排除B项。<br>第三空，代入验证，C项“掷地有声”形容话语铿锵有力，符合文意，当选。<br>故正确答案为C。<br>【文段出处】《他从不以“中国氢弹之父”自居》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":17,"pid":"p33696f0d7e"},{"qid":"4651944","no":14,"type":"语句表达","module":"言语理解与表达","stem":"<p>下列句子中，语序最恰当的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"参加集体婚礼的新人们今天早上都在滨江大道上在摄像机镜头前向大家笑容甜蜜地挥手致意。"},{"k":"B","t":"今天早上都在滨江大道上参加集体婚礼的新人们在摄像机镜头前笑容甜蜜地向大家挥手致意。"},{"k":"C","t":"在滨江大道上参加集体婚礼的新人们今天早上都在摄像机镜头前笑容甜蜜地向大家挥手致意。"},{"k":"D","t":"今天早上在滨江大道上参加集体婚礼的新人们都在摄像机镜头前笑容甜蜜地向大家挥手致意。"}],"answer":"D","multi":false,"explanation":"<p>根据选项内容可知，均为记叙的内容，依据记叙文六要素，应按照“时间、地点、人物、事情的起因、经过、结果”的顺序。“今天早上”为时间，“在滨江大道上”为地点，“参加集体婚礼的新人们”为人物，“在摄像机镜头前笑容甜蜜地向大家挥手致意”为事件，对应D项。<br>A项，“参加集体婚礼的新人们今天早上都在滨江大道上在摄像机镜头前”语序错误，时间、地点应该放到人物之前，排除；<br>B项，“今天早上都在滨江大道上参加集体婚礼的新人们”语序错误，“都”应该放在主语“新人们”之后，排除；<br>C项，“在滨江大道上参加集体婚礼的新人们今天早上都在摄像机镜头前”语序错误，时间应该放到地点之前，排除。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":18,"pid":"p33696f0d7e"},{"qid":"4651913","no":15,"type":"语句表达","module":"言语理解与表达","stem":"<p>下列句子中，有语病的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"有人戏言，人生最大的修行就是饥来餐饭倦来眠。作者在这本书中介绍了九十四道地方美食、九十四段独属于他的乡愁和对过往的回忆。"},{"k":"B","t":"随着海平面的上升，旅游胜地马尔代夫正面临灭顶的威胁。近年来，他们的旅游营销口号是：“趁我们还在这里，快来看看吧。”"},{"k":"C","t":"欧阳修的文学成就，在我国文学史上享有很高的地位，称他为北宋诗文革新运动的领袖和文坛盟主是实至名归的。"},{"k":"D","t":"“厦庇五洲客，门纳万顷涛。”九月的厦门，草木葱茏，生气勃勃。"}],"answer":"C","multi":false,"explanation":"<p>C项，“文学成就”与“地位”搭配不当，应改为“欧阳修在我国文学史上享有很高的地位······”，存在语病，当选。<br>A、B、D三项均表意明确，没有语病，排除。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":19,"pid":"p33696f0d7e"},{"qid":"4651928","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>下列选项中，两句话表达的意思不一致的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"（1）敢于这样做的人，难道不是一个英雄吗？（2）敢于这样做的人，肯定就是一个英雄。"},{"k":"B","t":"（1）看到这一幕，有谁会感到滑稽可笑呢？（2）看到这一幕，没有谁不感到滑稽可笑的。"},{"k":"C","t":"（1）谁说癌症是不可治愈的绝症？（2）癌症并非是不可治愈的绝症。"},{"k":"D","t":"（1）只要天不塌下来，他就会来。（2）除非天塌下来，他才会不来。"}],"answer":"B","multi":false,"explanation":"<p>A项，两句话意思均为“敢于这样做的人是英雄”，意思一致，排除；<br>B项，（1）句为反问句，意思为“看到这一幕，没有人会感到滑稽可笑”，（2）句意思为“看到这一幕谁都会感到滑稽可笑”，意思不一致，当选；<br>C项，两句话意思均为“癌症是可以治愈的”，意思一致，排除；<br>D项，两句话意思均为“他会来”，意思一致，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":20,"pid":"p33696f0d7e"},{"qid":"4651935","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>下列几个句子按顺序排列，语意最连贯的是：<br>①也就是通过人格的自我完善来达到永恒的生命境界<br>②这种感觉所带来的，决不仅仅是无可奈何的缕缕忧伤<br>③而更多地浸透着珍惜时光、热爱生命的积极进取精神<br>④正如诗中所写：“老冉冉其将至兮，恐修名之不立。”<br>⑤以及由此而产生的时不我待、分秒必争的急切心情</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"④①②③⑤"},{"k":"B","t":"④⑤②③①"},{"k":"C","t":"②④③①⑤"},{"k":"D","t":"②③①⑤④"}],"answer":"D","multi":false,"explanation":"<p>对比选项，确定首句。②句提到“这种感觉”，④句提到“正如诗中所写”，两句均有不适合作首句的特征，但从选项设置来看首句必须为二者之一，此时可观察②④两句前的指代或论证内容在所给的语句中是否出现，若有其指代或论证内容，则不合适作首句。对比可知，④句“老冉冉其将至兮，恐修名之不立”意思是我觉得老境将要渐渐到来，只担心美好的名声来不及树立，强调要有一种紧迫感、用好每一分每一秒，为⑤句的举例论证，因此④句不适合作首句；②句前应提及“某种感觉”，在已给语句中并无关于此话题的论述，故对比之下②句可作为首句，排除A、B两项。<br>根据⑤④两句构成捆绑，锁定D项。<br>故正确答案为D。<br>【文段出处】《中国古典诗歌中“生命意识”的内涵与泛化》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"p33696f0d7e"},{"qid":"4651942","no":18,"type":"语句表达","module":"言语理解与表达","stem":"<p>下列语句中理解上会产生歧义的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"我国的火箭目前只有一个名称，统一叫“长征”，如长征一号、长征二号、长征三号等，每个型号还根据发射的不同产品及轨道辅以ABCDE等系列。"},{"k":"B","t":"清代李渔在美食鲜蔬中很是推崇蕈，他认为“食此物者，犹吸山川草木之气，未有无益于人者也”。"},{"k":"C","t":"党的十九大闭幕不久，部分省市人大代表、政协委员就认真学习、座谈，畅谈自己的体会。"},{"k":"D","t":"被雨水洗刷过的天空分外澄净，被雨水冲洗过的树木更显青翠。"}],"answer":"C","multi":false,"explanation":"<p>C项，“部分”的修饰内容会产生歧义，可能是部分省市，也可能是省市的部分人大代表和政协委员，存在歧义，当选。<br>A、B、D三项均无歧义，表述正确，排除。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"p33696f0d7e"},{"qid":"4651960","no":19,"type":"片段阅读","module":"言语理解与表达","stem":"<p>抚今追昔，历史的车轮总会在字里行间留下深浅不一的痕迹，文字的变迁也在响应一个时代的风起云涌，并与之同频共振。殷商的甲骨文，证实了一个王朝的存在，并烙刻下诸多与国运生死攸关的大事；秦朝的小篆，见证了一统江山的恢宏，并因为“书同文”的国策实现了从多元向一元的转变；五四时期的白话文，记录了救亡图存的革命者为探寻出路而前赴后继、上下求索的历史，并在新文化运动的号召下焕然一新，顺应时代大势所趋。<br>对上文意思概括最为准确的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"语言文字折射并记录时代，同时也为时代所重塑和改变"},{"k":"B","t":"语言文字是时代最为活跃的要素，促进了时代的发展"},{"k":"C","t":"时代的发展和社会的进步使语言文字更加丰富"},{"k":"D","t":"任何时代都会有鲜明的政治、经济、文化特色，语言文字也不例外"}],"answer":"A","multi":false,"explanation":"<p>文段开篇提出观点，“历史的车轮总会在字里行间留下深浅不一的痕迹”，即历史会影响文字；另外，“文字的变迁也在响应一个时代的风起云涌，并与之同频共振”，即文字的变迁也能反映时代的特征。接着通过殷商的甲骨文、秦朝的小篆、五四时期的白话文这三个例子论证了前文观点。故文段重点在文段开篇观点句，即文字和时代的相互影响，对应A项。<br>B项，“语言文字是时代最为活跃的要素”文段未提及，无中生有，且未体现文字也会随时代而变迁之意，表述片面，排除；<br>C项，未体现文字会见证并记录时代之意，表述片面，排除；<br>D项，“任何时代都会有鲜明的政治、经济、文化特色”文段未提及，无中生有，排除。<br>故正确答案为A。<br>【文段出处】《尊重语言，就是尊重我们自己》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"p33696f0d7e"},{"qid":"4651952","no":20,"type":"语句表达","module":"言语理解与表达","stem":"<p>放眼知识原野，遍布鲜花秀草，亦多毒木荆棘。鱼龙混杂，良莠并存。古人说：“                    。”只有不唯书、戒盲从、善思考、勤探究，才能了解真相、认识规律、掌握真理。此乃读书之大道、治学之根本。<br>在横线中应填入的最恰当的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"人皆知以食愈饥，莫知以学愈愚"},{"k":"B","t":"尽信书，则不如无书"},{"k":"C","t":"六经三史，诸子百家，非无可观，皆足为治"},{"k":"D","t":"读书之法无他，惟是笃志虚心，反复详玩，为有功耳"}],"answer":"B","multi":false,"explanation":"<p>横线出现在文段中间，需要结合前后文内容进行分析。前文指出知识有好也有坏，后文指出不能一味相信书本，要善于思考，故横线处表达书的内容有好有坏，不能一味相信书本，B项“尽信书，则不如无书”意思是读书不要拘泥于书上或迷信书本，与前后文衔接恰当，当选。<br>A项，“人皆知以食愈饥，莫知以学愈愚”意思是人们都知道用食物去解决饥饿，却不知道用学习来驱除愚昧，文段并未体现用学习来驱除愚昧，与前后文衔接不当，排除；<br>C项，“六经三史，诸子百家，非无可观，皆足为治”意思是六经三史以及诸子百家的著作，并不是没有可以效法的，而且依照这些史籍所阐述的道理都足以治理好国家，侧重借助书籍可以治理国家，与前后文衔接不当，排除；<br>D项，“读书之法无他，惟是笃志虚心，反复详玩，为有功耳”意思是读书的方法没有别的，只有专心致志，虚心探索，深刻领会，才能收到成效，侧重读书要专心，与前后文衔接不当，排除。<br>故正确答案为B。<br>【文段出处】新华网《励学赋》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"p33696f0d7e"},{"qid":"4651915","no":21,"type":"片段阅读","module":"言语理解与表达","stem":"<p>运气学说，是探讨自然变化的周期性规律及其对人体健康和疾病影响的一门学问。这里讲的周期性规律，是基于自然界六气六律和五气更立的六、五节律，即五运六气节律。运气学说认为，天人合一是天人间动态节律的同步和谐，这是人体健康的基础，而天人合一的失调是一切疾病产生的根本原因。《黄帝内经》中的五运六气学说，传承发挥了中华文明的五六之律，凝聚了黄帝时代的文化精粹，是黄帝文化的活化石，故能成为打开中华文明宝库的钥匙。<br>上面文字说明的重点是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"运气学的丰富内涵"},{"k":"B","t":"研究运气学的意义"},{"k":"C","t":"“五运六气”在中华传统文化中的地位"},{"k":"D","t":"运气学探讨的“五运六气”的出处"}],"answer":"C","multi":false,"explanation":"<p>文段开篇引出“运气学说”这一概念，并指出“运气学说”中的“周期性规律”是基于“五运六气节律”而建立，进而引出“五运六气节律”这一话题。紧接着从运气学说中“天人合一”的和谐以及失调正反两个方面指出“节律”的重要性。尾句从《黄帝内经》来阐述“五运六气”传承中华文明的五六之律，凝聚黄帝时代的文化精粹，并通过“故”对前文进行总结，强调“五运六气”是打开中华文明宝库的钥匙，对应C项。<br>A项，“运气学的丰富内涵”对应首句引出话题部分，非重点，排除；<br>B项，“研究运气学的意义”文段未提及，无中生有，排除；<br>D项，“‘五运六气’的出处”文段未提及，无中生有，排除。<br>故正确答案为C。<br>【文段出处】光明日报《为什么说中医药学是打开中华文明宝库的钥匙》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"p33696f0d7e"},{"qid":"4651922","no":22,"type":"片段阅读","module":"言语理解与表达","stem":"<p>一部人类文明史，就是国与国之间不断对外开放的历史。无数事实已经昭示，唯有对外开放，才能顺应和平、发展、合作、共赢的时代潮流，才能契合各国追求发展的共同愿望。然而，各个国家的发展终究不是在同一起跑线上，有些国家已经步入发达国家行列，总担心别人“分肥”自己的发展红利，于是贸易壁垒搭起、单边主义盛行。把门关起来的逆向操作，只会拉开距离、产生摩擦。所以，要“坚持‘拉手’而不是‘松手’，坚持‘拆墙’而不是‘筑墙’”。<br>关于上文所运用的写作手法，下列分析不正确的一项是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"文段起笔运用概述历史的方式，阐明了开放才是国家文明的表现"},{"k":"B","t":"“把门关起来的逆向操作，只会拉开距离、产生摩擦”形象分析了建壁垒逆潮流而动的后果"},{"k":"C","t":"“坚持‘拆墙’而不是‘筑墙’”，既有引用，又有比喻和对比"},{"k":"D","t":"文段中的“拆墙”喻指有些国家实行的单边主义政策的自私本质"}],"answer":"D","multi":false,"explanation":"<p>A项，根据首句“一部人类文明史，就是国与国之间不断对外开放的历史”可知，“文章起笔运用概述历史的方式”表述正确，排除；<br>B项，“把门关起来的逆向操作，只会拉开距离、产生摩擦”中“把门关起来的逆向操作”对应“建壁垒逆潮流而动”，“只会拉开距离、产生摩擦”对应“后果”，表述正确，排除；<br>C项，“坚持‘拉手’而不是‘松手’，坚持‘拆墙’而不是‘筑墙’”引用自习近平主席在主旨演讲中所用的佳喻，并且“拆墙”和“筑墙”之间形成一组对比，故“既有引用，又用了比喻和对比”，表述正确，排除；<br>D项，根据“坚持‘拆墙’而不是‘筑墙’”可知，“拆墙”是一种积极的措施，强调要打破贸易壁垒，故与文意相悖，当选。<br>本题为选非题，故正确答案为D。<br>【文段出处】《【光明网评】对外开放，始终是中国发展的关键词》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"p33696f0d7e"},{"qid":"4651933","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>生活的起起落落，其实和四时变换是一样的道理，生活总会有高潮和低谷，但即便在低谷之中，我们也不必感到悲伤，在对未来的期待中，我们永远拥有不灭的希望。与此同时，我们也能用行动为自己赋予渡过难关的力量。<br>上述内容用一句诗来表达，最恰当的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"三十功名尘与土，八千里路云和月"},{"k":"B","t":"仰天大笑出门去，我辈岂是蓬蒿人"},{"k":"C","t":"人有悲欢离合，月有阴晴圆缺"},{"k":"D","t":"长风破浪会有时，直挂云帆济沧海"}],"answer":"D","multi":false,"explanation":"<p>文段开篇说明生活有高潮和低谷，接着通过转折标志词“但”强调在低谷时，我们要充满希望，并通过实际行动渡过难关。故文段重在强调希望与行动。D项“长风破浪会有时，直挂云帆济沧海”意为相信总有一天，我们能乘长风破万里浪，高高挂起云帆，在沧海中勇往直前，体现了面对困难时不绝希望，勇于拼搏，与文段重点相符，当选。<br>A项，“三十功名尘与土，八千里路云和月”意为多年功名犹如尘土微不足道，还需披星戴月付出更大的努力，强调要建功立业，精忠报国，偏离文段中心，排除；<br>B项，“仰天大笑出门去，我辈岂是蓬蒿人”意为仰面朝天纵声大笑着走出门去，我怎么会是长期身处草野之人，表现出狂傲自负与踌躇满志的人物形象，偏离文段中心，排除；<br>C项，“人有悲欢离合，月有阴晴圆缺”意为人们有离别的痛苦、团聚的欢欣，月亮也会有阴伏晴出、团圆亏损，强调人事总处在变化之中，有好的时候也有不好的时候，对应“四时变换”，为转折之前的内容，非重点，排除。<br>故正确答案为D。<br>【文段出处】《阴霾终究会被阳光驱散 困难终究会被努力打败》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"p33696f0d7e"},{"qid":"4651948","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>单层石墨烯的透光率高达97.7%，肉眼看过去几乎是完全透明的。它有着绝佳的导热性，热传导能力是金刚石的两倍以上。石墨烯的机械强度极大，比钢铁还要强200倍，如果把1平方米的单层石墨烯做成一张吊床，区区0.34纳米的厚度便可以稳稳地承载一只猫。石墨烯的导电性比银和铜还强，载流子迁移率比碳纳米管和硅还高。<br>上面文字表明：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"石墨烯的用途非常广泛"},{"k":"B","t":"石墨烯有许多普通材料不具备的优异性质"},{"k":"C","t":"人们对石墨烯的应用寄予厚望"},{"k":"D","t":"人们对石墨烯的研究已取得重大突破"}],"answer":"B","multi":false,"explanation":"<p>文段开篇指出石墨烯的透光率非常高，接着说明其热传导能力强于金刚石，并指出其机械强度高于钢铁、导电性优于银和铜、载流子迁移率比碳纳米管和硅还高，故文段为并列结构，强调石墨烯的各种性质优于其他材料，对应B项。<br>A项，“用途”仅对应“把1平方米的单层石墨烯做成一张吊床”，无法概括全文，表述片面，排除；<br>C项“人们对石墨烯的应用寄予厚望”、D项“取得重大突破”文段均未提及，无中生有，排除。<br>故正确答案为B。<br>【文段出处】《石墨烯，潜在应用令人惊喜》</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"p33696f0d7e"},{"qid":"4651955","no":25,"type":"片段阅读","module":"言语理解与表达","stem":"<p>社会变迁常是发生在旧有社会结构不能应付新环境的时候。新的环境发生了，人们最初遭遇到的是旧方法不能获得有效的结果，生活上发生了困难。人们不会在没有发觉旧方法不适用之前就把它放弃的。旧的生活方法有习惯的惰性。但是如果它已不能答复人们的需要，它终必会失去人们对它的信仰，守住一个没有效力的工具是没有意义的，会引起生活上的不便，甚至蒙受损失。另一方面，新的方法却又不是现存的，必须有人发明，或是有人向别种文化去学习、输入。此外，还得经过实验，才能被人接受，完成社会变迁的过程。<br>概括文段的主要内容，以下选项恰当的是：</p>","material":"<p>        孙坚字文台，吴郡富春人，盖孙武之后也。</p><p>        少为县吏。年十七，与父共载船至钱唐，会海贼胡玉等从匏里上掠取贾人财物，方於岸上分之，行旅皆住，船不敢进。坚谓父曰：“此贼可击，请讨之。”父曰：“非尔所图也。”坚行操刀上岸，以手东西指麾，若分部人兵以罗遮贼状。贼望见，以为官兵捕之，即委财物散走。坚追，斩得一级以还。父大惊。由是显闻，府召署假尉。</p><p>        会稽妖贼许昌起於句章，自称阳明皇帝，与其子韶扇动诸县，众以万数。坚以郡司马募召精勇，得千馀人，与州郡合讨破之。是岁，熹平元年也。刺史臧旻列上功状，诏书除坚盐渎丞，数岁徙盱眙丞，又徙下邳丞。</p>","materialNo":2,"options":[{"k":"A","t":"社会变迁是如何发生的"},{"k":"B","t":"新旧社会结构的交替"},{"k":"C","t":"社会环境如何适应时代发展"},{"k":"D","t":"社会生活习惯的改变与文化输入"}],"answer":"A","multi":false,"explanation":"<p>文段开篇指出社会变迁发生在旧有社会结构不能应付新环境的时候，接着进行详细的解释，即旧方法不能获得有效的结果就会失去人们对它的信仰，后文通过并列关联词“另一方面”指出有人发明新方法并经过试验后，才会完成社会变迁。文段意在强调发生社会变迁的过程，对应A项。<br>B项“新旧社会结构”、C项“社会环境”、D项“社会生活习惯”均缺少主题词“社会变迁”，排除。<br>故正确答案为A。<br>【文段出处】《乡土中国》名实的分离</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"p33696f0d7e"},{"qid":"4652026","no":1,"type":"逻辑判断","module":"判断推理","stem":"<p>根据材料信息，下列哪项是可能的？</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"甲和戊住在同一层，且甲是西向"},{"k":"B","t":"甲和丙住在同一层，且甲是西向"},{"k":"C","t":"丁和甲住在同一层，且甲是东向"},{"k":"D","t":"丁和乙住在同一层，且丁是东向"}],"answer":"A","multi":false,"explanation":"<p>本题属于组合排列材料题。问可能的情况，可优先考虑代入。<br>代入A项：甲与戊同一层，同时可以保证甲西向，戊东向；根据条件（1），乙与丙同一层，方向无约束；最后丁与己同一层，根据条件（2），丁东向则己西向即可，与材料不矛盾，即可能，当选；<br>代入B项：甲与丙同一层，则乙与甲或丙无法在同一层，与条件（1）冲突，排除；<br>代入C项：丁与甲同一层，甲是东向，则丁为西向，与条件（2）冲突，排除；<br>代入D项：丁与乙同一层，则乙与甲或丙无法在同一层，与条件（1）冲突，排除。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":30,"pid":"p33696f0d7e"},{"qid":"4652027","no":2,"type":"类比推理","module":"判断推理","stem":"<p>若己朝向是东向，则下列        项中的两户可能住在同一层。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"甲和己"},{"k":"B","t":"丁和丙"},{"k":"C","t":"乙和丙"},{"k":"D","t":"戊和丙"}],"answer":"B","multi":false,"explanation":"<p>第一步：分析题干。</p><p>①乙与甲或者丙住在同一层；</p><p>②丁朝向是东向；</p><p>③甲、戊两户1户东向、1户西向。</p><p>提问方式为“可能”，优先考虑代入法解题，题干信息较多可辅助列表。</p><p>第二步：逐一代入选项。</p><p>代入A项，甲和己在同一层，根据题中已知条件己朝向是东向及②丁是东向可知：</p><p><img src=\"assets/img/timu/17dac7edeb5de59.png\" class=\"fig\" style=\"width:547px;height:198px;\"></p><p>再根据①乙与甲或者丙住在同一层，甲已经和己在同一层，所以乙只能和丙在同一层，剩下戊只能和丁同一层。此时，戊和甲同为西向。</p><p><img src=\"assets/img/timu/17dac70a4cb9654.png\" class=\"fig\" style=\"width:597px;height:199px;\"></p><p>不满足③甲、戊两户1户东向、1户西向，排除；</p><p>代入B项，丁和丙在同一层，根据题中已知条件己朝向是东向及②丁是东向可知：</p><p><img src=\"assets/img/timu/17dac70e4db0fd8.png\" class=\"fig\" style=\"width:599px;height:197px;\"></p><p>结合③甲、戊两户1户东向、1户西向，以及①乙与甲或者丙住在同一层，可以得到如下表格：</p><p><img src=\"assets/img/timu/17dac7118107eb8.png\" class=\"fig\" style=\"width:601px;height:199px;\"></p><p>符合题干要求，当选；</p><p>代入C项，乙和丙在同一层，根据题中已知条件己朝向是东向及②丁是东向可知：</p><p><img src=\"assets/img/timu/17dac7157fca51a.png\" class=\"fig\" style=\"width:599px;height:199px;\"></p><p>剩下的甲和戊都是在西向，不满足③甲、戊两户1户东向、1户西向，排除；</p><p>代入D项，戊和丙在同一层，根据题中已知条件己朝向是东向及②丁是东向可知：</p><p><img src=\"assets/img/timu/17dac71a2b0f611.png\" class=\"fig\" style=\"width:599px;height:198px;\"></p><p>剩下的乙和甲分别在两层的西侧，不满足①乙与甲或者丙住在同一层，排除。</p><p>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":31,"pid":"p33696f0d7e"},{"qid":"4651908","no":3,"type":"类比推理","module":"判断推理","stem":"<p>翟志刚、王亚平、叶光富3名航天员乘神舟十三号载人飞船进入天和核心舱。在太空中，如果航天员想在天和核心舱中进行以下实验，其中最难完成的是               。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"将金粉和铜粉混合"},{"k":"B","t":"将牛奶加入水中混合"},{"k":"C","t":"用漏斗、滤纸过滤除去水中的泥沙"},{"k":"D","t":"用金属环制作水膜"}],"answer":"C","multi":false,"explanation":"<p>物质在天和核心舱中完全失重，所以需要重力的作用才能完成的实验难以进行。因为物质的混合与重力无关，所以金粉与铜粉的混合、牛奶与水的混合均可以在天和核心舱中实现，A、B两项均错误；用漏斗、滤纸过滤可以除去水中的泥沙，是因为将水与泥沙倒入放有滤纸的漏斗中时，水与泥沙受到重力的作用向下运动，水可以通过滤纸，而泥沙无法通过，所以水中的泥沙被去除，可见过滤操作需要利用重力，在天和核心舱中很难实现，C项正确；用金属环制作水膜时，水膜的形成是由于水的表面张力，与重力作用无关，在天和核心舱中可以实现，D项错误。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":32,"pid":"p33696f0d7e"},{"qid":"4651909","no":4,"type":"类比推理","module":"判断推理","stem":"<p>石油分馏是将几种不同沸点的混合物分离的一种方法，属于物理变化。右图是石油分馏塔的示意图，下列有关说法错误的是：</p><p><img src=\"assets/img/timu/17dacc799c1ce6d.png\" class=\"fig\" style=\"width:340px;height:345px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"石油是一种混合物"},{"k":"B","t":"a、b、c中沸点最高的是a"},{"k":"C","t":"柴油中碳元素的百分含量比重油低"},{"k":"D","t":"分馏的残留物还可以制得其他产品"}],"answer":"B","multi":false,"explanation":"<p>A项：石油是由多种烷烃、环烷烃等有机物组成的混合物，正确；<br>B项：石油分馏塔越往上温度越低，石油蒸气在石油分馏塔内上升的过程中，沸点高的物质会先进行液化，沸点低的物质则会逐渐上升，在塔的高处液化，所以越往上物质的沸点越低，所以a、b、c中沸点最高的是c，错误；<br>C项：由B项的分析可知重油的沸点比柴油的沸点高，沸点的高低与物质中碳原子的多少有关，物质中碳原子越多，物质的沸点也就越高，所以柴油中碳元素的百分含量比重油低，正确；<br>D项：石油分馏出的残留物主要是沥青，可以用于制造涂料、塑料等，正确。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":33,"pid":"p33696f0d7e"},{"qid":"4651910","no":5,"type":"类比推理","module":"判断推理","stem":"<p>汽车安全气囊中的填充物主要成分是<img src=\"assets/img/gongshi/formula-98cc6ac78fb66455.png\" class=\"tex\">、<img src=\"assets/img/gongshi/formula-3e2dc890b33d6ab9.png\" class=\"tex\">和<img src=\"assets/img/gongshi/formula-725ffeec41df8a2b.png\" class=\"tex\">。汽车发生猛烈碰撞时，<img src=\"assets/img/gongshi/formula-98cc6ac78fb66455.png\" class=\"tex\">分解，生成甲、乙两种单质，有关的化学方程式为<img src=\"assets/img/gongshi/formula-99ea22394171dc6b.png\" class=\"tex\">；<img src=\"assets/img/gongshi/formula-3e2dc890b33d6ab9.png\" class=\"tex\">的作用是与可能会对人体造成伤害的单质甲反应，生成单质乙和两种氧化物。以下推断错误的是<u>　　</u>。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"<p>汽车安全气囊里的气体是氮气</p>"},{"k":"B","t":"<p>单质甲是金属钠</p>"},{"k":"C","t":"<p>安全气囊中<img src=\"assets/img/gongshi/formula-98cc6ac78fb66455.png\" class=\"tex\">受到剧烈撞击反应迅速<br></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-3e2dc890b33d6ab9.png\" class=\"tex\">与单质甲反应后有氮氧化合物生成<br></p>"}],"answer":"D","multi":false,"explanation":"<p>A、B两项：金属钠（<img src=\"assets/img/gongshi/formula-da8916393f88c55e.png\" class=\"tex\">）为非常活泼的金属，接触皮肤会与皮肤表面的水分发生剧烈的化学反应，生成强碱<img src=\"assets/img/gongshi/formula-27668c22d4f9bcb0.png\" class=\"tex\">，会对人体造成伤害，而氮气（<img src=\"assets/img/gongshi/formula-8727fec00c8e3abb.png\" class=\"tex\">）不会对人体造成伤害，可知单质甲为金属钠，单质乙为氮气，根据反应方程式可知<img src=\"assets/img/gongshi/formula-98cc6ac78fb66455.png\" class=\"tex\">分解后产生了大量氮气，而<img src=\"assets/img/gongshi/formula-3e2dc890b33d6ab9.png\" class=\"tex\">也可以与<img src=\"assets/img/gongshi/formula-da8916393f88c55e.png\" class=\"tex\">反应生成氮气，因此安全气囊里的气体是氮气，A、B两项均正确；</p><p>C项：由于安全气囊需要在汽车发生事故的极短时间内充气来保护驾驶员和乘客，因此安全气囊中<img src=\"assets/img/gongshi/formula-98cc6ac78fb66455.png\" class=\"tex\">受到剧烈撞击后，会在极短时间内释放<img src=\"assets/img/gongshi/formula-8727fec00c8e3abb.png\" class=\"tex\">，即安全气囊中<img src=\"assets/img/gongshi/formula-98cc6ac78fb66455.png\" class=\"tex\">受到剧烈撞击反应迅速，正确；</p><p>D项：根据<img src=\"assets/img/gongshi/formula-3e2dc890b33d6ab9.png\" class=\"tex\">与<img src=\"assets/img/gongshi/formula-da8916393f88c55e.png\" class=\"tex\">反应生成单质乙和两种氧化物，单质乙为<img src=\"assets/img/gongshi/formula-8727fec00c8e3abb.png\" class=\"tex\">，则另外两种氧化物分别为钠的氧化物和钾的氧化物，故没有氮氧化合物生成，错误。</p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":34,"pid":"p33696f0d7e"},{"qid":"4651911","no":6,"type":"逻辑判断","module":"判断推理","stem":"<p>如图所示为一定质量的水的体积在0-<img src=\"assets/img/gongshi/formula-b74de021cf806f3e.png\" class=\"tex\">范围内随温度变化的图像。根据图像及水的其他性质，下列分析判断正确的是<u>　   　</u>。</p><p><img src=\"assets/img/timu/17dab3edd5361a8.png\" class=\"fig\" style=\"width:372px;height:287px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"<p>因热胀冷缩，任何情况下水的体积都随温度升高而增大</p>"},{"k":"B","t":"<p>在冬季气温为<img src=\"assets/img/gongshi/formula-173f6eda4951f9cd.png\" class=\"tex\">的情况下，池塘里水温可能是上热下冷</p>"},{"k":"C","t":"<p>在冬季气温为<img src=\"assets/img/gongshi/formula-173f6eda4951f9cd.png\" class=\"tex\">的情况下，池塘里水温可能是上冷下热</p>"},{"k":"D","t":"<p>夏季池塘中上层的水可能比下层的水凉<br></p>"}],"answer":"C","multi":false,"explanation":"<p>A项：根据图像可知，在0-<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">时，水的体积随温度的升高而减小，在大于<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">时，水的体积随温度的升高而增大，因此不是在任何情况下水的体积都随温度升高而增大，错误；</p><p>B、C两项：当冬季气温为<img src=\"assets/img/gongshi/formula-173f6eda4951f9cd.png\" class=\"tex\">时，池塘表面的水温接近外界气温，约为<img src=\"assets/img/gongshi/formula-173f6eda4951f9cd.png\" class=\"tex\">，由图像可知，一定质量的水在1℃时的体积大于在<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">时的体积，即水在<img src=\"assets/img/gongshi/formula-173f6eda4951f9cd.png\" class=\"tex\">时的密度小于在<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">时的密度，因此<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">的水会由于密度更大而下沉，所以冬季池塘里的水温可能是上冷下热，B项错误，C项正确；</p><p>D项：根据图像可知，在<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">以上时，随温度升高，水的体积增大，密度减小。在夏季（温度远大于<img src=\"assets/img/gongshi/formula-006ec1881bc9f5c2.png\" class=\"tex\">），池塘表面的水与气温接近，温度较高，则密度较小，而温度稍低的水会由于密度更大而沉到底部，即下层的水比上层的水凉，D项错误。</p><p>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":35,"pid":"p33696f0d7e"},{"qid":"4651912","no":7,"type":"逻辑判断","module":"判断推理","stem":"<p>如图所示为某人设计的一种测量装置的电路，其中AB部分为四分之一圆弧的电阻丝，一段柔软的细金属丝拴一小球悬挂于O点并与电阻丝良好接触，将其放在水平行驶的汽车中，则该装置可以测量汽车的<u>            </u>。</p><p><img src=\"assets/img/timu/17daea70266fc8d.png\" class=\"fig\" style=\"width:400px;height:362px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"速度大小，电压表数值越大，汽车速度越大"},{"k":"B","t":"速度大小，电压表数值越大，汽车速度越小"},{"k":"C","t":"加速度大小，电压表数值越大，汽车加速度越大"},{"k":"D","t":"加速度大小，电压表数值越大，汽车加速度越小"}],"answer":"C","multi":false,"explanation":"<p><img src=\"assets/img/timu/17dab49c5dbb2c0.png\" class=\"fig\" style=\"width:700px;height:361px;\"></p><p>如图所示，小球由细金属丝连接于O点，小球可绕O点摆动，当小球运动到图一所示的位置时，金属丝与电阻丝相交于C点，此时电压表测量AC段电阻两端电压；</p><p>若汽车做匀速直线运动，小球也做匀速直线运动，即处于平衡状态，则不会绕O点摆动，金属丝与电阻丝相交于A点，此时电压表无示数，故无法测量汽车速度大小，A、B两项错误；</p><p>若汽车水平方向存在加速度，小球与车的加速度相同，根据牛顿第二定律<img src=\"assets/img/gongshi/formula-70d0cff4e8b34c2e.png\" class=\"tex\">可知，小球水平方向的加速度越大，水平方向所需要的合外力越大，如图二所示，对小球进行受力分析，将小球受到的拉力分解成水平方向和竖直方向，竖直方向上的分力<img src=\"assets/img/gongshi/formula-dc24552ef53ae964.png\" class=\"tex\">与重力<img src=\"assets/img/gongshi/formula-e7901ed0abf04b48.png\" class=\"tex\">大小相等，方向相反，水平方向上的分力<img src=\"assets/img/gongshi/formula-1dc4ac8f9f76893d.png\" class=\"tex\">即为小球所受合外力，由受力分析图可知，<img src=\"assets/img/gongshi/formula-4a0bf715d84c2d51.png\" class=\"tex\">，若车的加速度越大，小球为了与车达到相同的加速度，需要更大的合外力，即<img src=\"assets/img/gongshi/formula-1dc4ac8f9f76893d.png\" class=\"tex\">也会更大，金属丝与竖直方向的夹角<img src=\"assets/img/gongshi/formula-58e44dd4eae5b9dc.png\" class=\"tex\">也越大，则AC段长度越大，电压表所检测部分电阻越大，根据串联分压规律可知，电压表示数将会越大。因此该装置可以用于测量汽车加速度大小，且电压表数值越大，表示汽车加速度越大。</p><p>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":36,"pid":"p33696f0d7e"},{"qid":"4652032","no":8,"type":"逻辑判断","module":"判断推理","stem":"<p>当远洋货轮从中纬度的东海开往赤道附近的过程中，由于地球赤道半径比两极半径更大，同一物体在低纬度所受的地心引力比高纬度地区小，因此可判断船在行进的过程中所受浮力会<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。假设海水的密度一定，则此过程中轮船排开水的体积<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"变小，不变"},{"k":"B","t":"变大，变小"},{"k":"C","t":"不变，不变"},{"k":"D","t":"变小，变大"}],"answer":"A","multi":false,"explanation":"<p>根据题意可知，同一物体在低纬度所受的地心引力比高纬度地区小，物体所受重力是由地心引力提供，所以物体在低纬度地区所受重力较小，则该船由中纬度地区向赤道附近（低纬度）行进的过程中，所受重力会变小，由于船舶始终漂浮于海面上，其所受浮力与重力大小相等，因此船舶所受浮力会变小，B、C两项均错误；根据重力公式<img src=\"assets/img/gongshi/formula-ef64c722412ae856.png\" class=\"tex\">可知，物体质量不变，重力减小是因为重力加速度<img src=\"assets/img/gongshi/formula-7e4eff27b2192bca.png\" class=\"tex\">变小，根据浮力公式<img src=\"assets/img/gongshi/formula-da6439e678639447.png\" class=\"tex\">，可知<img src=\"assets/img/gongshi/formula-aa6160481b27bb11.png\" class=\"tex\">，</p><p>当物体质量<img src=\"assets/img/gongshi/formula-3687b06690d5f464.png\" class=\"tex\">与液体密度<img src=\"assets/img/gongshi/formula-e1fc43d6b935f152.png\" class=\"tex\">不变时，<img src=\"assets/img/gongshi/formula-8c2927a839683d5b.png\" class=\"tex\">也不变，即轮船排开水的体积不变，A项正确，D项错误。</p><p>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":37,"pid":"p33696f0d7e"},{"qid":"4652037","no":9,"type":"逻辑判断","module":"判断推理","stem":"<p>应用储能介质（某种结晶水合物）储存和再利用太阳能是一项新技术。其原理是：当白天阳光照射时，储能介质熔化，同时吸收热能；当夜晚降温时，储能介质凝固，同时释放出热能。某地区白天气温可达<img src=\"assets/img/gongshi/formula-5606b56ef302540e.png\" class=\"tex\">，夜晚可下降至<img src=\"assets/img/gongshi/formula-37c5a57e9895e181.png\" class=\"tex\">，若应用上述技术调节室温，根据下表中几种常见的储能介质的数据，最佳选用<u>            </u>。</p><p><img src=\"assets/img/timu/17dac7ebd0d4e4f.png\" class=\"fig\" style=\"width:700px;height:154px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-8dc8681a1af0fe87.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-20c627d11a773f8d.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-d82770dfaef4f2fd.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-9e423fde7a19dfb6.png\" class=\"tex\"></p>"}],"answer":"B","multi":false,"explanation":"<p>根据题干信息可知，选取的物质需要满足白天能熔化、晚上能凝固的条件，也就是要求选取的物质熔点在<img src=\"assets/img/gongshi/formula-37c5a57e9895e181.png\" class=\"tex\">-<img src=\"assets/img/gongshi/formula-5606b56ef302540e.png\" class=\"tex\">的范围内，D项错误；根据表格中各结晶水合物熔化时吸收的热量大小可知，<img src=\"assets/img/gongshi/formula-20c627d11a773f8d.png\" class=\"tex\">单位质量可储存的能量最多，故最佳选用<img src=\"assets/img/gongshi/formula-20c627d11a773f8d.png\" class=\"tex\">为储能介质。</p><p>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":38,"pid":"p33696f0d7e"},{"qid":"4652038","no":10,"type":"类比推理","module":"判断推理","stem":"<p>F1赛车中，赛车手为了提升成绩，往往喜欢追求高速转弯。但高速转弯很容易侧滑出跑道引起事故。当赛车进入如图的弯道时，图中的4条路线中较合理的是<u>          </u>。</p><p><img src=\"assets/img/timu/17dacc6520bf558.png\" class=\"fig\" style=\"width:375px;height:381px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"虚线①"},{"k":"B","t":"实线②"},{"k":"C","t":"虚线③"},{"k":"D","t":"实线④"}],"answer":"B","multi":false,"explanation":"<p>赛车在转弯时做圆周运动，需要向心力，该向心力由车轮与地面之间的侧向静摩擦力提供，赛车高速转弯时若该静摩擦力不足以提供向心力，则赛车很容易侧滑出跑道。为避免赛车高速转弯时引起事故，根据向心力公式<img src=\"assets/img/gongshi/formula-fb480f25e22680e8.png\" class=\"tex\">可知，当赛车以相同的速度行驶时，轨道半径越大，所需向心力越小，越不容易侧滑出跑道，由图可知，2号轨道的半径最大，故选择2号路线。</p><p>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":39,"pid":"p33696f0d7e"},{"qid":"4652043","no":11,"type":"逻辑判断","module":"判断推理","stem":"<p>一般情况下，洗衣机在正常工作时是非常平稳的。而关掉电源以后，洗衣机先是振动越来越剧烈，之后振动又逐渐减弱直至停止振动。对这一现象，下列解释正确的是        。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"正常工作时，洗衣机波轮的运转频率比洗衣机的固有频率大很多"},{"k":"B","t":"正常工作时，洗衣机波轮的运转频率比洗衣机的固有频率小很多"},{"k":"C","t":"正常工作时，洗衣机波轮的运转频率与洗衣机的固有频率相等"},{"k":"D","t":"关掉电源后，洗衣机的固有振动频率发生了改变"}],"answer":"A","multi":false,"explanation":"<p>关掉电源以后，洗衣机波轮的运转频率逐渐降低，之所以振动越来越剧烈，是因为运转频率逐渐接近洗衣机的固有频率，发生了共振，当运转频率与固有频率相等时，振动达到最强，之后运转频率继续减小，逐渐远离洗衣机固有频率，振动越来越弱，可见在洗衣机正常工作时，波轮的运转频率大于洗衣机的固有频率，A项正确，B、C两项均错误；洗衣机的固有频率是其本身的属性，与其他因素无关，固有频率不会因关掉电源而发生变化，D项错误。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":40,"pid":"p33696f0d7e"},{"qid":"4652044","no":12,"type":"类比推理","module":"判断推理","stem":"<p>一款手机充电宝标有“20000mAh，5V”的字样，某手机电池的容量为“4200mAh，5V”。当上述的充电宝显示电量为45%时，对电量显示为55%的上述手机进行充电。充电时电流为2A，则        。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"充电宝恰好能把手机充足电"},{"k":"B","t":"充电宝不能将手机充足电"},{"k":"C","t":"手机充足电需要的时间约为1小时"},{"k":"D","t":"充电宝供电时是将电能转化为化学能"}],"answer":"C","multi":false,"explanation":"<p>mAh为电量单位，充电宝剩余电量为<img src=\"assets/img/gongshi/formula-bee5cf544e785dc8.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-e5b57224970fa020.png\" class=\"tex\">，手机充满电需要的电量为<img src=\"assets/img/gongshi/formula-b10f35c5e687e1a9.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-4f4297e130fba7e2.png\" class=\"tex\">，远远小于充电宝剩余电量，故充电宝不仅可以把手机电池的电量充满，还会有电量剩余，故A、B两项错误；根据电流定义公式可知<img src=\"assets/img/gongshi/formula-9a48a38f86fc98b3.png\" class=\"tex\">，充电时间<img src=\"assets/img/gongshi/formula-3b79ea66c9c1c0e1.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-45337c86760dbb09.png\" class=\"tex\">，故手机充满电需要的时间约为1小时，C项正确；充电宝供电是化学能转变为电能的过程，D项错误。</p><p>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":41,"pid":"p33696f0d7e"},{"qid":"4652047","no":13,"type":"逻辑判断","module":"判断推理","stem":"<p>如图所示为蜂鸟在空中悬停的受力分析，根据图示内容判断蜂鸟能够悬停的主要原因是：</p><p><img src=\"assets/img/timu/17dacc7334ce11b.png\" class=\"fig\" style=\"width:650px;height:376px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"蜂鸟振翅的频率高，每秒可达50~70次"},{"k":"B","t":"蜂鸟振翅的幅度大"},{"k":"C","t":"蜂鸟振翅的方向非常接近水平面"},{"k":"D","t":"蜂鸟体重轻"}],"answer":"C","multi":false,"explanation":"<p>一般鸟类上下扇动翅膀时，不但会得到升力，还会得到向前的力，因此既会上升，同时也会往前飞。蜂鸟可以自由调节其翅膀的角度，由图可见，蜂鸟振翅的方向非常接近水平面，这导致其几乎不会获得向前的动力，而会获得与竖直方向很接近的净升力。若将净升力进行分解，其水平方向的分力将与净阻力在水平方向的分力平衡，因此净升力与净阻力的合力为竖直向上，刚好能与竖直向下的重力平衡，从而使蜂鸟悬停在空中。因此，蜂鸟悬停的关键因素是其振翅的方向，C项正确。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":42,"pid":"p33696f0d7e"},{"qid":"4652034","no":14,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是（    ）。</p><p><img src=\"assets/img/timu/17daea320c779c4.png\" class=\"fig\" style=\"width:650px;height:314px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。观察发现，小黑球每次顺时针平移3步，位置依次在线的外端、线的内部循环；小箭头每次顺时针平移2步，位置依次在线的内部、线的外端循环。因此？处图形的小黑球应在左侧横线的外端，小箭头应在左侧横线的内部，只有C项符合。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":43,"pid":"p33696f0d7e"},{"qid":"4652031","no":15,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是（    ）。</p><p><img src=\"assets/img/timu/17dadae65c46094.png\" class=\"fig\" style=\"width:700px;height:386px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。题干出现多个小元素，优先考虑元素的种类和个数。观察发现，题干每幅图形均出现了4种元素，且每种元素的数量呈4、2、2、1分布，故？处应选择一个由4种元素构成，且每种元素的数量分别是4、2、2、1的图形，只有A项符合。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":44,"pid":"p33696f0d7e"},{"qid":"4652042","no":16,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是（    ）。</p><p><img src=\"assets/img/timu/17dac8598869e4c.png\" class=\"fig\" style=\"width:600px;height:337px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。每幅图位于左上角的元素沿顺时针移动1格，位于左下角的元素沿逆时针移动2格，位于右上角的元素沿顺时针移动1格，位于右下角的元素沿顺时针移动2格，位于顶部的元素移动到中间，位于中间的元素移动到左下角，只有B项符合。<br>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":45,"pid":"p33696f0d7e"},{"qid":"4652033","no":17,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是（    ）。</p><p><img src=\"assets/img/timu/17dac777f84e78d.png\" class=\"fig\" style=\"width:600px;height:263px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>图形元素组成相似，且相同线条重复出现，优先考虑样式规律中的加减同异。观察发现，在第一组图形中，第一个图形与第二个图形的右上部分去同存异得到第三个图形的右上部分，第一个图形与第二个图形的左下部分求同得到第三个图形的左下部分，故第二组图形应遵循同样的规律，只有D项符合。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":46,"pid":"p33696f0d7e"},{"qid":"4651982","no":18,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是（    ）。</p><p><img src=\"assets/img/timu/17dadb8d55c34b1.png\" class=\"fig\" style=\"width:700px;height:318px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。黑点先在外圈按照逆时针方向，每次移动4格，到图四走完外圈所有位置之后图五进入内圈，继续逆时针移动4格，到？处应该在图形第三行第三列的位置（移动轨迹如下图红线所示）；<img src=\"assets/img/gongshi/formula-4c7b72ff33532287.png\" class=\"tex\">先在外圈按照逆时针方向，每次移动3格，到图五经历完外圈之后，图六进入内圈继续逆时针移动3格，到？处应该在图形第二行第三列的位置（移动轨迹如下图蓝线所示）；×在外圈按照逆时针方向，每次移动2格，到？处应该在图形第五行第三列的位置（移动轨迹如下图黄线所示），只有D项符合。</p><p><img src=\"assets/img/timu/17dadbdf7c598cd.png\" class=\"fig\" style=\"width:474px;height:171px;\"></p><p>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":47,"pid":"p33696f0d7e"},{"qid":"4651991","no":19,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是：</p><p><img src=\"assets/img/timu/17daeb33f2e48bd.png\" class=\"fig\" style=\"width:600px;height:320px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成相似，优先考虑样式规律。观察发现，第一组图一中圆圈和方块互换得到图二，排除C、D两项。继续观察发现，第一组图一中带有黑圆的阴影部分在图二中没有保留，故第二组中图一带有黑方块的阴影部分也不应该保留，只有A项符合。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":48,"pid":"p33696f0d7e"},{"qid":"4651995","no":20,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形的变化规律的是：</p><p><img src=\"assets/img/timu/17dac57641481e9.png\" class=\"fig\" style=\"width:591px;height:286px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。第一组图1上下翻转后得到<img src=\"assets/img/timu/17dac5bb1a74167.png\" class=\"fig\" style=\"width:81px;height:97px;\"> ，左右两个小元素位置互换，梯形内部黑白颜色互换得到图2；第二组遵循相同规律，图1上下翻转后得到<img src=\"assets/img/timu/17dac5bea444f12.png\" class=\"fig\" style=\"width:81px;height:106px;\">，左右两个小元素位置互换，半圆内部黑白颜色互换得到C项。</p><p>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":49,"pid":"p33696f0d7e"},{"qid":"4651997","no":21,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中，符合所给图形变化规律的是：</p><p><img src=\"assets/img/timu/17dae67c6baf14d.png\" class=\"fig\" style=\"width:583px;height:313px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>解法一：元素组成不同，可以考虑数量规律。观察发现，题干图形明显被分割，可以考虑面数量。题干图形的面数量依次为6、8、10、8、？，可以得出根据题干图3左右两边图形面数量对称，故？处图形的面数量应为6，只有D项满足规律。<br>故正确答案为D。<br>解法二：元素组成不同，可以考虑属性规律。观察发现，题干图形依次为轴+中心对称图形、非对称图形、轴+中心对称图形、非对称图形、？，可以得出题干图形为轴+中心对称图形与非对称图形交替出现，故？处图形应为轴+中心对称图形，只有C项满足规律。<br>故正确答案为C。<br>注：本题这两种解题规律都不常规，上海考生简单了解基本解题思路即可，其他省份考生无需作为备考重点。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":50,"pid":"p33696f0d7e"},{"qid":"4652004","no":22,"type":"图形推理","module":"判断推理","stem":"<p>下列选项中立方体①肯定能转成立方体②的是：</p><p><img src=\"assets/img/timu/17dadcd3f8bbad9.png\" class=\"fig\" style=\"width:700px;height:182px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>将每个面标上序号，如下图所示，逐一分析选项。</p><p><img src=\"assets/img/timu/17dadce0b5acb6e.png\" class=\"fig\" style=\"width:700px;height:174px;\"></p><p>A项：以三个面的公共点为起点，在面a内沿顺时针方向画边，立方体①中边1与面a内的线条垂直，立方体②中边1与面a内的线条平行，立方体①和立方体②中的三个面相对位置不同，因此立方体①不一定能转成立方体②，排除；</p><p>B项：立方体①中面a内的斜线指向三个面的公共点，而立方体②中面a内的斜线不指向三个面的公共点，立方体①和立方体②中的三个面相对位置不同，因此立方体①不一定能转成立方体②，排除；</p><p>C项：立方体①中面a内的斜线指向三个面的公共点，而立方体②中面a内的斜线不指向三个面的公共点，立方体①和立方体②中的三个面相对位置不同，因此立方体①不一定能转成立方体②，排除；</p><p>D项：以三个面的公共点为起点，在面a内沿逆时针方向画边，立方体①中边1与面a内的线条垂直，立方体②中边1也与面a内的线条垂直，因此立方体①和立方体②中的三个面相同，且相对位置也没有问题，立方体①肯定能转成立方体②，当选。</p><p>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":51,"pid":"p33696f0d7e"},{"qid":"4651963","no":23,"type":"类比推理","module":"判断推理","stem":"<p>把（1）图放在最左边，（2）（3）（4）图放在后面，共有6种排列，其中<u>        </u>能使四图之间存在逻辑关系。</p><p><img src=\"assets/img/timu/17dac51f49040fd.png\" class=\"fig\" style=\"width:580px;height:146px;\"></p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"只有一种排列"},{"k":"B","t":"有两种排列"},{"k":"C","t":"有三种排列"},{"k":"D","t":"有四种排列"}],"answer":"B","multi":false,"explanation":"<p>题干每幅图均由大圆形、小圆形、小黑点和短折线组成，元素组成相同，优先考虑位置规律。根据题干要求，把（1）图放在最左边，（2）（3）（4）图放在后面，共有6种排列顺序。当排列顺序为（1）（2）（3）（4）时，小黑点绕着小圆形每次顺时针旋转<img src=\"assets/img/gongshi/formula-d49189d80272a7c6.png\" class=\"tex\">，短折线按照在大圆形的右侧、左侧、右侧、左侧的顺序交替出现，四图之间存在逻辑关系。</p><p><img src=\"assets/img/timu/17dac54dda79f4c.png\" class=\"fig\" style=\"width:580px;height:181px;\"></p><p>当排列顺序为（1）（4）（3）（2）时，小黑点绕着小圆形每次逆时针旋转<img src=\"assets/img/gongshi/formula-d49189d80272a7c6.png\" class=\"tex\">，短折线按照在大圆形的右侧、左侧、右侧、左侧的顺序交替出现，四图之间存在逻辑关系。</p><p><img src=\"assets/img/timu/17dac551759c6a8.png\" class=\"fig\" style=\"width:617px;height:179px;\"></p><p>当排列顺序为（1）（2）（4）（3）、（1）（3）（2）（4）、（1）（3）（4）（2）或（1）（4）（2）（3）时，小黑点和短折线的位置均不存在逻辑关系。故共有两种排列能使四图之间存在逻辑关系。</p><p>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":52,"pid":"p33696f0d7e"},{"qid":"4651988","no":24,"type":"图形推理","module":"判断推理","stem":"<p>将下列六个图形按一定规律分为两大类，正确的是：</p><p><img src=\"assets/img/timu/17dac565b65d9ef.png\" class=\"fig\" style=\"width:462px;height:369px;\"></p>","options":[{"k":"A","t":"①③⑥，②④⑤"},{"k":"B","t":"①③⑤，②④⑥"},{"k":"C","t":"①⑤⑥，②③④"},{"k":"D","t":"①②④，③⑤⑥"}],"answer":"C","multi":false,"explanation":"<p>本题为分组分类题目。观察发现，每个图形都有两个小黑点，考虑功能元素。将题干图形的两个小黑点进行连线后发现，图①⑤⑥中两个小黑点的连线与图形内部线条垂直，图②③④中两个小黑点的连线与图形内部线条平行，故图①⑤⑥为一组，图②③④为一组。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":53,"pid":"p33696f0d7e"},{"qid":"2616493","no":25,"type":"图形推理","module":"判断推理","stem":"<p>下列两组图形均由（1）（2）（3）三个图形组成，三个图形之间存在一定变化规律。按其规律右边这组图形中，图（3）应为：</p><p><img src=\"assets/img/timu/180cfc827c33ab8.png\" class=\"fig\" style=\"width:700px;height:279px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>本题为两组图形式，先看第一组图找规律。观察发现，图（1）和图（2）元素组成相同，考虑位置规律，图（1）顺时针旋转<img src=\"assets/img/gongshi/formula-d49189d80272a7c6.png\" class=\"tex\">可以得到图（2）；图（3）与前两幅图元素组成相似，有相同线条重复出现，考虑样式规律，图（1）图（2）相加可以得到图（3）。第二组遵循此规律，图（1）旋转<img src=\"assets/img/gongshi/formula-d49189d80272a7c6.png\" class=\"tex\">后得到图（2）如下图所示，图（1）图（2）相加得到图（3），只有C项符合，当选。</p><p><img src=\"assets/img/timu/180cfc89fad4ece.png\" class=\"fig\" style=\"width:164px;height:208px;\"></p><p>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":54,"pid":"p33696f0d7e"},{"qid":"4652016","no":26,"type":"逻辑判断","module":"判断推理","stem":"<p>处于北方的甲城干旱少雨，高大的乔木树种在这里无法存活，南方常见的阔叶树种在这里几乎看不到，生长在甲城的树都是耐旱树，即使是市民在室内种植的盆栽树种也以松柏类为主。<br>根据以上陈述，可以得出下列（    ）项。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"市民在室内种植的盆栽树种在南方不常见"},{"k":"B","t":"有些耐旱树并不是高大的乔木树种"},{"k":"C","t":"有些生长在南方的松柏类树种可以长成高大的乔木"},{"k":"D","t":"有些阔叶树也可以在室内种植"}],"answer":"B","multi":false,"explanation":"<p>日常结论题，根据题干信息逐一分析选项。<br>A项：题干中指出“市民在室内种植的盆栽树种以松柏类为主”，但并未提及松柏类在南方是否常见，无中生有，无法推出，排除；<br>B项：题干中指出“高大的乔木树种在甲城无法存活”“生长在甲城的树都是耐旱树”，说明生长在甲城的这些耐旱树不是高大的乔木，可以推出，当选；<br>C项：文段没有提及生长在南方的松柏类树种，无中生有，无法推出，排除；<br>D项：题干中指出“阔叶树种在甲城几乎看不到”“市民在室内种植的盆栽树种以松柏类为主”，并未提及阔叶树是否可以在室内种植，无中生有，无法推出，排除。<br>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":55,"pid":"p33696f0d7e"},{"qid":"4652020","no":27,"type":"逻辑判断","module":"判断推理","stem":"<p>在一次人工智能测试中，测试员让一个人类被试者和人工智能一起回答同一组试题，得到两份答案。另一群不知情的专家通过分析两份答案来判断哪一份出自人类，哪一份出自计算机，结果判断的错误率接近50%。看起来人工智能表现过于优异，其智能水平远超预期。有人认为，这个结果表明试题本身的设计可能有问题。<br>为了使上述结论成立，下列（    ）项命题最适合作为补充条件。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"这个人工智能之前并没有通过图灵测试"},{"k":"B","t":"专家的判断能力是很强的"},{"k":"C","t":"测试员并没有在测试过程中作弊"},{"k":"D","t":"该人工智能从设计上不应该与人类有如此接近的表现"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：这个结果表明试题本身的设计可能有问题。<br>论据：在一次人工智能测试中，测试员让一个人类被试者和人工智能一起回答同一组试题，得到两份答案。另一群不知情的专家通过分析两份答案来判断哪一份出自人类，哪一份出自计算机，结果判断的错误率接近50%。看起来人工智能表现过于优异，其智能水平远超预期。<br>本题论据说的是人工智能表现过于优异，论点说的是试题可能有问题，论点和论据话题不一致，优先考虑搭桥，即在“人工智能表现过于优异”和“试题本身设计可能有问题”之间建立联系。<br>第二步：逐一分析选项。<br>A项：该项指出人工智能之前没有通过图灵测试（注：图灵测试是一种测试机器是不是具备人类智能的方法），即在图灵测试中，这个人工智能不具备人类智能，试题可能真的有问题，补充论据加强，保留；<br>B项：该项指出专家的判断能力是很强的，说明论据的可信度很高，补充论据加强，保留；<br>C项：测试员没有作弊，肯定了人工智能优异表现的客观性，补充论据加强，保留；<br>D项：该人工智能从设计上不应该与人类有如此接近的表现，即不可能过于优秀得让专家判断不出来谁是计算机谁是人类，所以可能是试题本身存在问题，建立了“人工智能表现过于优异”和“试题本身设计可能有问题”之间的联系，搭桥项，可以加强，保留。<br>对比上述选项，搭桥的加强力度大于补充论据，D项当选。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":56,"pid":"p33696f0d7e"},{"qid":"4651931","no":28,"type":"逻辑判断","module":"判断推理","stem":"<p>业主小赵问物业公司的老王：“你是物业公司的员工吗？”<br>老王：“是的。”<br>小赵：“物业是为业主服务的吗？”<br>老王：“是的。”<br>小赵：“那么，你为什么不为我服务？”<br>下列（    ）项和上述小赵的论证错误最为类似。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"甲乙两国是邻邦，所以，作为两国人的你我应该成为好朋友"},{"k":"B","t":"你们村应该感谢我们公司每年提供大量无息贷款和捐赠物资，所以，你应该感谢我"},{"k":"C","t":"每片雪花都不愿意承认自己是雪崩的罪魁祸首，但其实每片雪花都对雪崩负有责任"},{"k":"D","t":"张某、陈某都是甲地人，他们两人都获得了医学博士学位，由此可见，甲地出医学人才"}],"answer":"B","multi":false,"explanation":"<p>第一步：分析题干论证方式。<br>题干为物业为“业主”服务，这里的“业主”是整体概念，而小赵偷换概念，变成了“每一位业主”，即为小赵个人服务，论证错误为“整体概念”被偷换为其中的“每个人概念”。<br>第二步：逐一分析选项。<br>A项：该项中甲乙两国是“邻邦”，即相邻，你和我应该成为好朋友，即关系好，前后说的完全是两件不同的事，而题干都在说“服务”，与题干逻辑错误不一致，排除；<br>B项：该项中你们村应该感谢我们公司，这里“我们公司”是整体概念，而句中偷换概念，变成了个人“我”，与题干逻辑错误一致，当选；<br>C项：该项中前后两句的“每片雪花”都是在表达每个个体的意思，前后并没有偷换概念，与题干逻辑错误不一致，排除；<br>D项：该项中张某、陈某都是甲地人，且都获得医学博士学位，所以推出甲地出医学人才，属于从部分推出整体，与题干逻辑错误不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":57,"pid":"p33696f0d7e"},{"qid":"4651945","no":29,"type":"逻辑判断","module":"判断推理","stem":"<p>宫观位于高山之巅，层峦拥翠，巉岩宿云，登临其上，顿感天近云低，有如离尘绝世。宫后有亭，登亭纵目，眼底群峦，尽伏槛下，清江如带，横呈天际，平畴庐舍，宛若图画。想到所见道观所在无不是名山大川，游览者小陈推测，古代道观的选址，一定都在风景绝美之处。<br>下列各项如果为真，（    ）项最能质疑小陈的推测。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"不仅是道教建筑处于名山大川，其他宗教建筑大多也风景如画"},{"k":"B","t":"由于长期以来环保意识薄弱，许多道观周边风景遭到了很大的破坏"},{"k":"C","t":"周边景色一般的道观，往往地处城镇，历经战乱和改建，基本消失绝迹了"},{"k":"D","t":"“小隐隐于野，中隐隐于市，大隐隐于朝”真正的道德之士追求的是精神的净土和心灵的宁静"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点与论据。<br>论点：古代道观的选址，一定都在风景绝美之处。<br>论据：所见道观所在无不是名山大川。<br>论点论据均在探讨道观选址风景优美，话题一致，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项说的是其他宗教建筑大多也风景如画，而论点讨论的是古代道观选址是否都在风景绝美之处，话题不一致，无法削弱，排除；<br>B项：该项说的是许多道观周边风景遭到了破坏，与论点讨论的古代道观选址是否都在风景绝美之处无关，话题不一致，无法削弱，排除；<br>C项：该项指出道观也会选址在周边景色一般的地方，只不过由于战乱和改建的原因而绝迹看不到了，直接削弱论点，当选；<br>D项：该项说的是真正的道德之士追求的是精神的净土和心灵的宁静，与论点讨论的古代道观选址是否都在风景绝美之处无关，话题不一致，无法削弱，排除。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":58,"pid":"p33696f0d7e"},{"qid":"4651956","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>去年全年甲城市的空气质量优良天数比乙城市的空气质量优良天数多了15%。因此，甲城市的管理者去年在环境保护和治理方面采取的措施比乙城市的更加有效。<br>下列哪项问题的答案最能对上述结论做出评价？</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"甲、乙两个城市在环境保护和治理方面采取的措施有何不同"},{"k":"B","t":"在环境保护和治理方面采取的措施能否在短时间内起到提升空气质量的效果"},{"k":"C","t":"甲城市的居民因空气质量引发的健康问题是否比乙城市更少"},{"k":"D","t":"如果采取了甲城市的措施，乙城市的空气质量是否也能得到显著提升"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：甲城市的管理者去年在环境保护和治理方面采取的措施比乙城市的更加有效。<br>论据：去年全年甲城市的空气质量优良天数比乙城市的空气质量优良天数多了15%。<br>第二步：逐一分析选项。<br>A项：讨论甲、乙两个城市采取的措施的差异，但论点讨论的是甲、乙两个城市哪个城市的措施更有效，话题不一致，无法评价，排除；<br>B项：讨论环境保护和治理方面采取的措施的时效性，但论点讨论的是甲、乙两个城市哪个城市的措施更有效，话题不一致，无法评价，排除；<br>C项：讨论甲、乙两个城市居民的健康问题，但论点讨论的是甲、乙两个城市哪个城市的措施更有效，话题不一致，无法评价，排除；<br>D项：讨论甲、乙两个城市措施的效果，如果采取了甲城市的措施，乙城市的空气质量可以显著提升，则说明甲城市的措施比乙城市的更有效果。反之，则无法证明甲城市的措施比乙城市的更有效，可以评价，当选。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":59,"pid":"p33696f0d7e"},{"qid":"4651973","no":31,"type":"逻辑判断","module":"判断推理","stem":"<p>为了明确B型烟粉虱和温室白粉虱在温度逆境下的生存特性对其种群发展的影响，研究人员对其进行了高温和低温暴露试验。结果表明，B型烟粉虱和温室白粉虱对温度逆境的适应性存在差异：B型烟粉虱对高温的适应性要高于温室白粉虱；温室白粉虱对高温敏感，但对低温的适应性要显著高于B型烟粉虱。研究人员据此推测，两种粉虱对温度逆境适应性的差异是导致其种群发展存在差异的一个重要原因。<br>下列各项如果为真，                    项能支持上述研究人员的推测。<br>（1）B型烟粉虱和温室白粉虱的卵、伪蛹和成虫在37℃～45℃下暴露1～2小时，其存活率均随着温度的上升而降低；<br>（2）B型烟粉虱的卵、伪蛹和成虫在37℃、39℃、41℃、43℃、45℃下暴露1～2小时后，3种供试虫态的存活率均高于温室白粉虱；<br>（3）B型烟粉虱在2℃下暴露2～12天，各供试虫态的存活率迅速下降，卵、2～3龄若虫、伪蛹在2℃下暴露12天后均不能存活，成虫在2℃下暴露4天后也全部死亡；而温室白粉虱卵、伪蛹在2℃下暴露12天后其存活率还能超过45%，成虫在2℃下暴露7天后仍有80%能够存活。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"仅（1）（2）"},{"k":"B","t":"仅（1）（3）"},{"k":"C","t":"仅（2）（3）"},{"k":"D","t":"（1）（2）（3）均可"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：两种粉虱对温度逆境适应性的差异是导致其种群发展存在差异的一个重要原因。<br>论据：B型烟粉虱对高温的适应性要高于温室白粉虱；温室白粉虱对高温敏感，但对低温的适应性要显著高于B型烟粉虱。<br>论点讨论的是两种粉虱对温度适应性的差异导致了种群发展差异，论据解释了B型烟粉虱对高温的适应性更高，温室白粉虱对低温的适应性更高，即讨论了两种粉虱对温度适应性的差异，论点、论据话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>（1）：两种粉虱在37℃～45℃下暴露相同时间时，存活率均随着温度的上升而降低，说明两种粉虱在相同温度下暴露相同时间，其存活情况相同，削弱论点，无法支持；<br>（2）：B型烟粉虱在37℃、39℃、41℃、43℃、45℃下存活率均高于温室白粉虱，说明B型烟粉虱在相对较高的温度下，适应性高于温室白粉虱，补充论据，可以支持；<br>（3）：在2℃下，B型烟粉虱的存活率低于温室白粉虱，说明在相对低温下，温室白粉虱的适应性高于B型烟粉虱，补充论据，可以支持。<br>综上，仅（2）（3）项能支持上述研究人员的推测。<br>故正确答案为C。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":60,"pid":"p33696f0d7e"},{"qid":"4651987","no":32,"type":"逻辑判断","module":"判断推理","stem":"<p>虫洞和黑洞都是爱因斯坦广义相对论预言的特殊时空结构，黑洞的存在已经被观测所证实，而虫洞依然属于理论假定。如果能证明虫洞真的存在，天文学研究将获得巨大突破。在近期的一项研究中，研究人员通过数值模拟的方法，发现黑洞落入虫洞会产生一种特殊的引力波频率渐降的信号——“反啾啾声”，这与双黑洞碰撞所产生的引力波频率渐高的“啾啾声”是不同的。研究者据此推测，未来人们可以根据这种特殊的引力波信号来搜寻宇宙中可能存在的虫洞。<br>以下各项如果为真，（    ）项最能质疑上述研究者的推测。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"黑洞落入虫洞后可能存在三种结局：一是瞬间穿过虫洞到达另外一个宇宙；二是停留在虫洞喉部；三是黑洞落入虫洞后，由于引力的相互作用，又被拉回到原来的宇宙"},{"k":"B","t":"黑洞围绕大质量天体绕行时，如果其运行的是椭圆轨道，所产生的引力波频率会不断变化，渐近时频率会逐渐增高，渐远时频率会逐渐降低"},{"k":"C","t":"黑洞落入虫洞后，由于引力的相互作用，又被拉回到原来的宇宙，此时他发出的引力波频率越来越小，发出“反啾啾声”"},{"k":"D","t":"在此次研究中，研究人员模拟了一个五倍太阳质量黑洞，落入一个稳定、不旋转、可穿越的200倍太阳质量虫洞"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：未来人们可以根据这种特殊的引力波信号来搜寻宇宙中可能存在的虫洞。<br>论据：研究人员通过数值模拟的方法，发现黑洞落入虫洞会产生一种特殊的引力波频率渐降的信号——“反啾啾声”，这与双黑洞碰撞所产生的引力波频率渐高的“啾啾声”是不同的。<br>论点论据均在讨论黑洞落入虫洞会产生一种特殊的引力波频率渐降的信号，可利用该信号搜寻虫洞，论点论据话题一致，削弱优先考虑削弱论点，即无法通过引力波频率渐降的信号来搜寻虫洞。<br>第二步：逐一分析选项。<br>A项：黑洞落入虫洞后可能存在三种结局，但未明确指出这三种结局与引力波频率渐降的信号之间的关系，无法得知是否可以通过引力波频率渐降的信号来搜寻虫洞，无关选项，排除；<br>B项：黑洞围绕大质量天体绕行时，如果其运行的是椭圆轨道，渐远时引力波频率会逐渐降低，而宇宙中的大质量天体并非只有虫洞，那么即便探测到引力波频率渐降的信号，也不代表搜寻到了虫洞，所以就无法通过引力波频率渐降的信号来搜寻虫洞，削弱论点，当选；<br>C项：解释了黑洞落入虫洞后会发出“反啾啾声”的原因，补充论据，为加强项，排除；<br>D项：详细描述了研究人员的研究内容，与论点讨论的通过引力波频率渐降的信号来搜寻虫洞无关，无关选项，排除。<br>故正确答案为B。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":61,"pid":"p33696f0d7e"},{"qid":"4652009","no":33,"type":"类比推理","module":"判断推理","stem":"<p>某小型规划设计工作室总共有42人，小明说：“这个工作室应该有人有注册规划类的证书”，小李说：“这个工作室应该有人没有注册规划类的证书”，小王说：“工作室的负责人应该没有注册规划类的证书”。若只有一个人说对了，那么这个工作室有        人有注册规划类的证书。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"42"},{"k":"B","t":"41"},{"k":"C","t":"1"},{"k":"D","t":"0"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出题干反对命题。<br>（1）有人有注册规划类的证书；<br>（2）有人没有注册规划类的证书；<br>（3）工作室的负责人应该没有注册规划类的证书。<br>条件（1）与（2）为两个“有的”，必有一真。而根据只有一个人说对了可知唯一的一真在条件（1）和（2）中，那么条件（3）一定为假。<br>第二步：看其余。<br>根据条件（3）为假，其矛盾命题“工作室的负责人有注册规划类的证书”为真，可推出条件（1）有人有注册规划类的证书为真。由于题干只有一句话为真，那么条件（2）为假，其矛盾命题“所有人都有注册规划类证书”为真，所有人即为42人，对应A项。<br>故正确答案为A。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":62,"pid":"p33696f0d7e"},{"qid":"4652000","no":34,"type":"逻辑判断","module":"判断推理","stem":"<p>近年来，面向大众的哲学教育逐渐普及到了青少年甚至儿童群体中。让孩子在很小的时候接受思想的启蒙与教化是一件好事。但是，从事这一教育工作的大部分教师的本职工作都是在高校中教授哲学，对于青少年的哲学教育并没有统一标准和成熟的纲领计划。如果哲学教师不懂得青少年的心智发展规律，使用不恰当的教育方式，反而对孩子的心智开发没有正面效果，甚至弊大于利。<br>下面（    ）项最能够成为上述结论的例证。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"张老师想让初中同学理解哲学与自然科学的关联，经常在哲学课上提到自然科学中的案例"},{"k":"B","t":"王老师每次上课都使用自己的PPT进行生动的解释说明，但很少引用哲学家的原著或原话来阐发哲学观点"},{"k":"C","t":"赵老师希望告诉学生严密的论证对于哲学思想具有关键意义，在课程中展示了许多推理与反驳的案例"},{"k":"D","t":"李老师为了让实验小学的学生明白阅读经典哲学家的原著对于理解哲学的必要性，规定同学每天回家阅读至少20页德国哲学家胡塞尔的巨著《纯粹现象学与现象学哲学的观念》"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：如果哲学教师不懂得青少年的心智发展规律，使用不恰当的教育方式，反而对孩子的心智开发没有正面效果，甚至弊大于利。<br>论据：无<br>本题只有论点没有论据，且提问方式为“下面哪项最能够成为上述结论的例证”，加强考虑补充论据，说明不恰当的教育方式对孩子的心智开发没有正面效果。<br>第二步：逐一分析选项。<br>A项：张老师通过举例的方式帮助初中同学理解哲学与自然科学的关联，是恰当的教育方式，因此无法成为例证，无法加强，排除；<br>B项：王老师利用PPT生动地为学生解释说明，很少直接用哲学家的话来阐发观点，该做法便于学生理解和接受，是恰当的教育方式，因此无法成为例证，无法加强，排除；<br>C项：赵老师通过案例帮助学生理解严密论证的意义，是恰当的教育方式，因此无法成为例证，无法加强，排除；<br>D项：李老师让实验小学的学生每天读哲学家胡塞尔的巨著，该方式是不恰当的，因为小学生的识字、阅读、理解能力都有限，而哲学家的哲学原著往往较为晦涩，所以学生的阅读会异常艰难，无法达到良好的效果，甚至可能引发学生的畏难和抵触情绪，带来负面影响，可以成为例证，可以加强，当选。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":63,"pid":"p33696f0d7e"},{"qid":"4652021","no":35,"type":"类比推理","module":"判断推理","stem":"<p>阿根廷大学的一位老师让五位留学生看校史上的五位大数学家的画像，让每位学生任意挑选两幅画像说出名字。<br>张说：“2号是高斯，3号是黎曼。”<br>倪说：“1号是希尔伯特，2号是闵可夫斯基。”<br>朱说：“3号是闵可夫斯基，5号是希尔伯特。”<br>韦说：“2号是高斯，4号是外尔。”<br>方说：“4号是外尔，1号是黎曼。”<br>老师发现每位学生都只说对了一半，那么1号画像是        。</p>","material":"<p>一小区某单元共3层住着甲、乙、丙、丁、戊、己6户人家。每层2户，1户东向，1户西向。已知：</p><p>（1）乙与甲或者丙住在同一层；</p><p>（2）丁朝向是东向；</p><p>（3）甲、戊两户1户东向、1户西向。</p>","materialNo":1,"options":[{"k":"A","t":"黎曼"},{"k":"B","t":"闵可夫斯基"},{"k":"C","t":"希尔伯特"},{"k":"D","t":"高斯"}],"answer":"D","multi":false,"explanation":"<p>此题为组合排列题，题干信息不确定，优先考虑代入法解题。<br>代入A项，1号是黎曼，要保证张说的只对一半，则2号是高斯，但此时倪的说法均错误，不符合题干要求，排除；<br>代入B项，1号是闵可夫斯基，此时倪的说法均错误，不符合题干要求，排除；<br>代入C项，1号是希尔伯特，要保证朱说的只对一半，则3号是闵可夫斯基，此时要保证张说的只对一半，则2号是高斯，要保证韦说的只对一半，则4号不是外尔，但此时方的说法均错误，不符合题干要求，排除；<br>代入D项，1号是高斯，可推出3号是黎曼，2号是闵可夫斯基，5号是希尔伯特，4号是外尔，符合题干要求，当选。<br>故正确答案为D。</p>","from":{"file":"2022年上海市公务员录用考试《行测》题（B类）（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"p33696f0d7e"}]};
